insert into public.paths (id, sort, title, subtitle, status) values
  ($uxg$P01$uxg$, 0, $uxg${"en":"Forms That Flow","ar":"نماذج تسير بسلاسة"}$uxg$::jsonb, $uxg${"en":"Design forms people can finish, understand and recover from, in English and Arabic.","ar":"صمّم نماذج يستطيع الناس إكمالها وفهمها وتصحيح أخطائهم فيها بسهولة، بالعربية والإنجليزية."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P02$uxg$, 1, $uxg${"en":"Find and Fix Usability","ar":"اكتشف مشكلات الاستخدام وأصلحها"}$uxg$::jsonb, $uxg${"en":"Use the 10 usability heuristics to spot what makes a screen hard to use, and pick the fix that helps.","ar":"استخدم مبادئ الاستخدام العشرة (Usability heuristics) لتكتشف ما يجعل الشاشة صعبة الاستخدام، وتختار الإصلاح الذي يساعد."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P05$uxg$, 2, $uxg${"en":"Make UX Accessible","ar":"اجعل تجربة المستخدم (UX) مناسبة للجميع"}$uxg$::jsonb, $uxg${"en":"Find and remove the barriers that stop people with disabilities, older users and everyone else from finishing their tasks.","ar":"اكتشف العوائق التي تمنع ذوي الإعاقة وكبار السن وغيرهم من إكمال مهامهم، وأزِلها."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P10$uxg$, 3, $uxg${"en":"Visual Hierarchy in Action","ar":"التسلسل البصري عمليًا"}$uxg$::jsonb, $uxg${"en":"Help people see what matters first, on any screen and in any language.","ar":"ساعد الناس على رؤية الأهم أولًا، على أي شاشة وبأي لغة."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P12$uxg$, 4, $uxg${"en":"Design Better AI Experiences","ar":"صمّم تجارب ذكاء اصطناعي أفضل"}$uxg$::jsonb, $uxg${"en":"Decide where AI truly helps people, set honest expectations, and keep people in control when it gets things wrong.","ar":"قرّر أين يساعد الذكاء الاصطناعي الناس فعلًا، واجعل توقّعاتهم صحيحة، وأبقِ الناس متحكّمين حين يخطئ."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P13$uxg$, 5, $uxg${"en":"AI Tools for Better UX","ar":"أدوات الذكاء الاصطناعي لتجربة مستخدم أفضل"}$uxg$::jsonb, $uxg${"en":"Use AI to draft, research and design faster, while you keep the judgment, check the facts and stay close to real users.","ar":"استخدم الذكاء الاصطناعي لتكتب وتبحث وتصمّم أسرع، على أن يبقى القرار لك، وتتحقّق من المعلومات، وتبقى قريبًا من المستخدمين الحقيقيين."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P14$uxg$, 6, $uxg${"en":"Patterns That Fit","ar":"أنماط في مكانها الصحيح"}$uxg$::jsonb, $uxg${"en":"Pick the right interface pattern for the moment: dialogs, sheets, messages, search and filters.","ar":"اختر نمط الواجهة المناسب للّحظة: الـ Dialogs، والـ Bottom sheets، والرسائل، والبحث، والفلاتر."}$uxg$::jsonb, $uxg$published$uxg$),
  ($uxg$P15$uxg$, 7, $uxg${"en":"Write Words That Work","ar":"اكتب كلمات تؤدّي المهمة"}$uxg$::jsonb, $uxg${"en":"Write screen text people can scan, understand and act on, in a tone that fits the moment.","ar":"اكتب نصوص الشاشات (UX writing) بحيث يتصفّحها الناس بسرعة ويفهمونها ويتصرّفون بها، وبنبرة تناسب الموقف."}$uxg$::jsonb, $uxg$published$uxg$)
insert into public.units (id, path_id, sort, title, free) values
  ($uxg$P01-U01$uxg$, $uxg$P01$uxg$, 0, $uxg${"en":"Ask only what you need","ar":"اسأل فقط عمّا تحتاجه"}$uxg$::jsonb, true),
  ($uxg$P01-U02$uxg$, $uxg$P01$uxg$, 1, $uxg${"en":"Pick the right control","ar":"اختر عنصر التحكّم المناسب"}$uxg$::jsonb, false),
  ($uxg$P01-U03$uxg$, $uxg$P01$uxg$, 2, $uxg${"en":"Keep labels and hints in sight","ar":"أبقِ العناوين والتلميحات ظاهرة"}$uxg$::jsonb, false),
  ($uxg$P01-U04$uxg$, $uxg$P01$uxg$, 3, $uxg${"en":"Errors people can fix","ar":"أخطاء يستطيع الناس إصلاحها"}$uxg$::jsonb, false),
  ($uxg$P01-U05$uxg$, $uxg$P01$uxg$, 4, $uxg${"en":"Forms everyone can finish","ar":"نماذج يستطيع الجميع إكمالها"}$uxg$::jsonb, false),
  ($uxg$P02-U01$uxg$, $uxg$P02$uxg$, 5, $uxg${"en":"Keep people informed, in their words","ar":"أخبِر الناس بما يحدث، بكلماتهم"}$uxg$::jsonb, true),
  ($uxg$P02-U02$uxg$, $uxg$P02$uxg$, 6, $uxg${"en":"Let people back out, and keep things the same","ar":"دَع الناس يتراجعون، واجعل التصميم متّسقًا"}$uxg$::jsonb, false),
  ($uxg$P02-U03$uxg$, $uxg$P02$uxg$, 7, $uxg${"en":"Stop errors early, and don't make people remember","ar":"امنع الأخطاء مبكرًا، ولا تُجبر الناس على التذكّر"}$uxg$::jsonb, false),
  ($uxg$P02-U04$uxg$, $uxg$P02$uxg$, 8, $uxg${"en":"Speed up regulars, cut the clutter","ar":"سرّع المعتادين، واحذف الزوائد"}$uxg$::jsonb, false),
  ($uxg$P02-U05$uxg$, $uxg$P02$uxg$, 9, $uxg${"en":"Help people recover, and find help","ar":"ساعد الناس على إصلاح أخطائهم، وعلى إيجاد المساعدة"}$uxg$::jsonb, false),
  ($uxg$P05-U01$uxg$, $uxg$P05$uxg$, 10, $uxg${"en":"See the barriers","ar":"اكتشف ما يوقف المستخدمين"}$uxg$::jsonb, true),
  ($uxg$P05-U02$uxg$, $uxg$P05$uxg$, 11, $uxg${"en":"Colour and contrast","ar":"الألوان والتباين"}$uxg$::jsonb, false),
  ($uxg$P05-U03$uxg$, $uxg$P05$uxg$, 12, $uxg${"en":"Keyboard and focus","ar":"لوحة المفاتيح والتركيز"}$uxg$::jsonb, false),
  ($uxg$P05-U04$uxg$, $uxg$P05$uxg$, 13, $uxg${"en":"Screen readers and meaning","ar":"قارئ الشاشة والمعنى"}$uxg$::jsonb, false),
  ($uxg$P05-U05$uxg$, $uxg$P05$uxg$, 14, $uxg${"en":"Touch, motion and time","ar":"اللمس والحركة والوقت"}$uxg$::jsonb, false),
  ($uxg$P10-U01$uxg$, $uxg$P10$uxg$, 15, $uxg${"en":"Put the decision first","ar":"ضع القرار أولًا"}$uxg$::jsonb, true),
  ($uxg$P10-U02$uxg$, $uxg$P10$uxg$, 16, $uxg${"en":"Group what belongs together","ar":"اجمع العناصر المترابطة معًا"}$uxg$::jsonb, false),
  ($uxg$P10-U03$uxg$, $uxg$P10$uxg$, 17, $uxg${"en":"Give emphasis a job","ar":"اجعل للبروز وظيفة"}$uxg$::jsonb, false),
  ($uxg$P10-U04$uxg$, $uxg$P10$uxg$, 18, $uxg${"en":"Keep the meaning on a small screen","ar":"حافظ على المعنى في الشاشة الصغيرة"}$uxg$::jsonb, false),
  ($uxg$P10-U05$uxg$, $uxg$P10$uxg$, 19, $uxg${"en":"Let real words stretch it","ar":"صمّم للكلمات الحقيقية"}$uxg$::jsonb, false),
  ($uxg$P10-U06$uxg$, $uxg$P10$uxg$, 20, $uxg${"en":"Check what you claimed","ar":"تحقّق مما ادّعيته"}$uxg$::jsonb, false),
  ($uxg$P12-U01$uxg$, $uxg$P12$uxg$, 21, $uxg${"en":"Does it need AI?","ar":"هل يحتاج ذكاءً اصطناعيًا؟"}$uxg$::jsonb, true),
  ($uxg$P12-U02$uxg$, $uxg$P12$uxg$, 22, $uxg${"en":"Set the right expectations","ar":"اجعل توقّعات الناس صحيحة"}$uxg$::jsonb, false),
  ($uxg$P12-U03$uxg$, $uxg$P12$uxg$, 23, $uxg${"en":"Explain and earn the right trust","ar":"اشرح واكسب الثقة المناسبة"}$uxg$::jsonb, false),
  ($uxg$P12-U04$uxg$, $uxg$P12$uxg$, 24, $uxg${"en":"Keep people in control","ar":"اترك التحكّم للناس"}$uxg$::jsonb, false),
  ($uxg$P12-U05$uxg$, $uxg$P12$uxg$, 25, $uxg${"en":"Fail gracefully","ar":"تعامَل مع الفشل بلطف"}$uxg$::jsonb, false),
  ($uxg$P13-U01$uxg$, $uxg$P13$uxg$, 26, $uxg${"en":"Let AI draft, you decide","ar":"دع الذكاء الاصطناعي يكتب المسوّدة، وقرّر أنت"}$uxg$::jsonb, true),
  ($uxg$P13-U02$uxg$, $uxg$P13$uxg$, 27, $uxg${"en":"Write prompts that work","ar":"اكتب طلبات (Prompts) تعطيك ما تحتاجه"}$uxg$::jsonb, false),
  ($uxg$P13-U03$uxg$, $uxg$P13$uxg$, 28, $uxg${"en":"Check what AI tells you","ar":"تحقّق ممّا يخبرك به الذكاء الاصطناعي"}$uxg$::jsonb, false),
  ($uxg$P13-U04$uxg$, $uxg$P13$uxg$, 29, $uxg${"en":"Research faster with AI","ar":"ابحث أسرع بالذكاء الاصطناعي"}$uxg$::jsonb, false),
  ($uxg$P13-U05$uxg$, $uxg$P13$uxg$, 30, $uxg${"en":"Design with AI, keep the judgment","ar":"صمّم بالذكاء الاصطناعي، والقرار لك"}$uxg$::jsonb, false),
  ($uxg$P14-U01$uxg$, $uxg$P14$uxg$, 31, $uxg${"en":"Interrupt only when it's worth it","ar":"لا تقاطع إلا حين يستحق الأمر"}$uxg$::jsonb, true),
  ($uxg$P14-U02$uxg$, $uxg$P14$uxg$, 32, $uxg${"en":"Show what's needed, make the next step obvious","ar":"أظهر المطلوب، ووضّح الخطوة التالية"}$uxg$::jsonb, false),
  ($uxg$P14-U03$uxg$, $uxg$P14$uxg$, 33, $uxg${"en":"Help people find it","ar":"ساعد الناس على إيجاد ما يبحثون عنه"}$uxg$::jsonb, false),
  ($uxg$P14-U04$uxg$, $uxg$P14$uxg$, 34, $uxg${"en":"Choices people can trust","ar":"اختيارات يثق بها الناس"}$uxg$::jsonb, false),
  ($uxg$P14-U05$uxg$, $uxg$P14$uxg$, 35, $uxg${"en":"Forms people finish","ar":"نماذج يكملها الناس"}$uxg$::jsonb, false),
  ($uxg$P14-U06$uxg$, $uxg$P14$uxg$, 36, $uxg${"en":"Numbers and dates, set fast","ar":"أرقام وتواريخ تُضبط بسرعة"}$uxg$::jsonb, false),
  ($uxg$P15-U01$uxg$, $uxg$P15$uxg$, 37, $uxg${"en":"Write for people who scan","ar":"اكتب لمن يقرأ بسرعة"}$uxg$::jsonb, true),
  ($uxg$P15-U02$uxg$, $uxg$P15$uxg$, 38, $uxg${"en":"Say more with fewer words","ar":"قل أكثر بكلمات أقل"}$uxg$::jsonb, false),
  ($uxg$P15-U03$uxg$, $uxg$P15$uxg$, 39, $uxg${"en":"Pick the right tone","ar":"اختر النبرة المناسبة"}$uxg$::jsonb, false),
  ($uxg$P15-U04$uxg$, $uxg$P15$uxg$, 40, $uxg${"en":"Labels that say what happens","ar":"نصوص (Labels) تقول ماذا سيحدث"}$uxg$::jsonb, false),
  ($uxg$P15-U05$uxg$, $uxg$P15$uxg$, 41, $uxg${"en":"Words for empty screens and alerts","ar":"كلمات للشاشات الفارغة والتنبيهات"}$uxg$::jsonb, false)
insert into public.skills (id, unit_id, title, criterion) values
  ($uxg$SK-P01-U01-01$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Cut the fields the form doesn't need","ar":"احذف الحقول التي لا يحتاجها النموذج"}$uxg$::jsonb, $uxg${"en":"Remove fields nobody uses, while keeping every field the task really needs.","ar":"احذف الحقول التي لا يستخدمها أحد، مع الإبقاء على كل حقل تحتاجه المهمّة فعلًا."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-02$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Postpone what can wait","ar":"أجّل ما يمكن أن ينتظر"}$uxg$::jsonb, $uxg${"en":"Move questions that are needed only later to the step where they're needed.","ar":"انقل الأسئلة التي لا تلزم إلا لاحقًا إلى الخطوة التي تحتاجها."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-03$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Explain why you ask for personal details","ar":"اشرح لماذا تطلب البيانات الشخصية"}$uxg$::jsonb, $uxg${"en":"Say at the field who sees a personal detail and what it's used for.","ar":"وضّح عند الحقل مَن يرى المعلومة الشخصية ولماذا تُستخدم."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-04$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Mark required and optional fields","ar":"وضّح الحقول الإلزامية والاختيارية"}$uxg$::jsonb, $uxg${"en":"Put a star on every required field and label the few optional ones, at the field.","ar":"ضع نجمة على كل حقل إلزامي واكتب «اختياري» على الحقول الاختيارية القليلة، عند الحقل نفسه."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-05$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Keep the check true to the label","ar":"اجعل التحقّق مطابقًا للتسمية"}$uxg$::jsonb, $uxg${"en":"Make sure a field labelled optional is never blocked when left empty.","ar":"تأكّد أن النموذج يقبل الحقل المكتوب عليه «اختياري» إذا تُرك فارغًا."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-06$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Ask for a name in one field","ar":"اطلب الاسم في حقل واحد"}$uxg$::jsonb, $uxg${"en":"Use one full-name field that fits every naming pattern.","ar":"استخدم حقلًا واحدًا للاسم الكامل يناسب كل أنماط الأسماء."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-07$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Accept numbers the way people write them","ar":"اقبل الأرقام كما يكتبها الناس"}$uxg$::jsonb, $uxg${"en":"Accept spaces, dashes and country codes in phone numbers, and tidy them for people.","ar":"اقبل المسافات والشَرطات ورموز الدول في أرقام الهواتف، ودع النظام يرتّبها بدلًا من الناس."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-08$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Use labels and formats people understand","ar":"استخدم تسميات وصيغًا يفهمها الناس"}$uxg$::jsonb, $uxg${"en":"Replace internal terms with plain words, and spell out months in dates.","ar":"استبدل المصطلحات الداخلية بكلمات بسيطة، واكتب أسماء الشهور في التواريخ."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-01$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Use a toggle only for instant settings","ar":"استخدم الـ Toggle للإعدادات الفورية فقط"}$uxg$::jsonb, $uxg${"en":"Use a toggle when the change happens at once, and a checkbox when it waits for a button.","ar":"استخدم الـ Toggle عندما يحدث التغيير فورًا، والـ Checkbox عندما ينتظر الضغط على زر."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-02$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"One answer or several, shown not hidden","ar":"إجابة واحدة أم عدة، معروضة لا مخفية"}$uxg$::jsonb, $uxg${"en":"Use radio buttons for one of a few, checkboxes for any number, and skip the dropdown for short lists.","ar":"استخدم الـ Radio buttons لإجابة واحدة من خيارات قليلة، والـ Checkboxes لأي عدد، وتجنّب القائمة المنسدلة للقوائم القصيرة."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-03$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Choose defaults with care","ar":"اختر القيم الافتراضية بعناية"}$uxg$::jsonb, $uxg${"en":"Preselect a safe, common choice, and never preselect a guess about someone personally.","ar":"اختر مسبقًا خيارًا آمنًا وشائعًا، ولا تختر مسبقًا أبدًا إجابة شخصية بالتخمين."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-04$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Let people type what they know","ar":"دع الناس يكتبون ما يعرفونه"}$uxg$::jsonb, $uxg${"en":"Use a typed field for values people know by heart, like a year or a date far away.","ar":"استخدم حقلًا للكتابة للقيم التي يحفظها الناس، مثل سنة أو تاريخ بعيد."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-05$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Show only the choices that are available","ar":"اعرض الخيارات المتاحة فقط"}$uxg$::jsonb, $uxg${"en":"Grey out dates and times that can't be booked, instead of rejecting them afterwards.","ar":"اجعل التواريخ والأوقات غير المتاحة باهتة، بدل رفضها بعد اختيارها."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-06$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Pick the right control for numbers","ar":"اختر العنصر المناسب للأرقام"}$uxg$::jsonb, $uxg${"en":"Use a stepper for small counts with a usual value, typing for large or exact numbers, and a text box beside any slider.","ar":"استخدم الـ Stepper للأعداد الصغيرة ذات القيمة المعتادة، والكتابة للأرقام الكبيرة أو الدقيقة، ومربع نص بجانب أي Slider."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-07$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Treat codes as text made of digits","ar":"تعامل مع الرموز كنص من أرقام"}$uxg$::jsonb, $uxg${"en":"Give IDs and codes a text field with the number pad, so leading zeros and length stay intact.","ar":"أعطِ الأرقام التعريفية والرموز حقلًا نصيًا بلوحة أرقام، حتى تبقى الأصفار في البداية والطول كما هي."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-08$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Make long lists searchable and forgiving","ar":"اجعل البحث في القوائم الطويلة سهلًا ويتقبّل الأخطاء"}$uxg$::jsonb, $uxg${"en":"Let people type to narrow long lists, suggest matches for typos, and pin common options without preselecting them.","ar":"دع الناس يكتبون لتضييق القوائم الطويلة، واقترح نتائج للأخطاء الإملائية، وثبّت الخيارات الشائعة في الأعلى دون اختيارها مسبقًا."}$uxg$::jsonb),
  ($uxg$SK-P01-U03-01$uxg$, $uxg$P01-U03$uxg$, $uxg${"en":"Label fields outside the box","ar":"ضع عنوان الحقل خارج المربع"}$uxg$::jsonb, $uxg${"en":"Give every field a visible label outside it, instead of placeholder text that vanishes.","ar":"أعطِ كل حقل عنوانًا ظاهرًا خارجه، بدل نص داخلي (Placeholder) يختفي."}$uxg$::jsonb),
  ($uxg$SK-P01-U03-02$uxg$, $uxg$P01-U03$uxg$, $uxg${"en":"Keep hints visible while typing","ar":"أبقِ التلميحات ظاهرة أثناء الكتابة"}$uxg$::jsonb, $uxg${"en":"Put format hints and examples outside the field, where they stay while people type.","ar":"ضع تلميحات الصيغة والأمثلة خارج الحقل، حيث تبقى أثناء الكتابة."}$uxg$::jsonb),
  ($uxg$SK-P01-U03-03$uxg$, $uxg$P01-U03$uxg$, $uxg${"en":"Don't hide what people need in a tooltip","ar":"لا تُخفِ ما يحتاجه الناس في Tooltip"}$uxg$::jsonb, $uxg${"en":"Show information people need to finish on the screen, not behind an info icon or hover.","ar":"اعرض المعلومات التي يحتاجها الناس لإكمال المهمة على الشاشة، لا خلف أيقونة معلومات أو تمرير الماوس."}$uxg$::jsonb),
  ($uxg$SK-P01-U03-04$uxg$, $uxg$P01-U03$uxg$, $uxg${"en":"Put each label right above its field","ar":"ضع كل عنوان فوق حقله مباشرة"}$uxg$::jsonb, $uxg${"en":"Place each label above its own field and closer to it than to any other field.","ar":"ضع كل عنوان فوق حقله، وأقرب إليه من أي حقل آخر."}$uxg$::jsonb),
  ($uxg$SK-P01-U03-05$uxg$, $uxg$P01-U03$uxg$, $uxg${"en":"One column, grouped","ar":"عمود واحد، في مجموعات"}$uxg$::jsonb, $uxg${"en":"Lay out fields in a single column, with related fields grouped under a short heading.","ar":"رتّب الحقول في عمود واحد، مع جمع الحقول المترابطة تحت عنوان رئيسي قصير."}$uxg$::jsonb),
  ($uxg$SK-P01-U03-06$uxg$, $uxg$P01-U03$uxg$, $uxg${"en":"Say the rules before people type","ar":"اذكر القواعد قبل أن يكتب الناس"}$uxg$::jsonb, $uxg${"en":"State exact requirements, like password rules or a required format, before the person types.","ar":"اذكر الشروط بدقة، مثل قواعد كلمة المرور أو الصيغة المطلوبة، قبل أن يكتب الشخص."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-01$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Show the error next to its field","ar":"اعرض الخطأ بجوار حقله"}$uxg$::jsonb, $uxg${"en":"Place each error message right by the field it is about, where people look while fixing it.","ar":"ضع كل رسالة خطأ بجوار الحقل الذي تخصّه مباشرة، حيث ينظر الناس أثناء الإصلاح."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-02$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Say what's wrong and how to fix it","ar":"اذكر ما الخطأ وكيف يُصلح"}$uxg$::jsonb, $uxg${"en":"Write errors in plain words that name the problem and the fix, with no codes or jargon.","ar":"اكتب الأخطاء بكلمات بسيطة تذكر المشكلة والحل، بلا أكواد أو مصطلحات تقنية."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-03$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Don't blame the person","ar":"لا تلُم الشخص"}$uxg$::jsonb, $uxg${"en":"Phrase errors politely, about the input, not about what the person did wrong.","ar":"صُغ الأخطاء بأدب، عمّا كُتب، لا عن خطأ ارتكبه الشخص."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-04$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Wait until people leave the field","ar":"انتظر حتى يغادر الناس الحقل"}$uxg$::jsonb, $uxg${"en":"Check a field when the person moves on, not while they are still typing.","ar":"تحقّق من الحقل حين ينتقل الشخص لغيره، لا وهو ما زال يكتب."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-05$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Keep what people typed","ar":"احتفظ بما كتبه الناس"}$uxg$::jsonb, $uxg${"en":"Keep every answer, including the wrong one, so people fix it instead of starting over.","ar":"احتفظ بكل إجابة، حتى الخاطئة، ليُصلحها الناس بدل أن يبدؤوا من جديد."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-06$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Signal errors with more than color","ar":"أظهر الخطأ بأكثر من اللون"}$uxg$::jsonb, $uxg${"en":"Mark an error with words and an icon too, not only a red border.","ar":"علّم الخطأ بكلمات وأيقونة أيضًا، لا بإطار أحمر فقط."}$uxg$::jsonb),
  ($uxg$SK-P01-U04-07$uxg$, $uxg$P01-U04$uxg$, $uxg${"en":"Sum up errors at the top of long forms","ar":"اجمع الأخطاء أعلى النماذج الطويلة"}$uxg$::jsonb, $uxg${"en":"On a long form, add a short list of errors at the top, and keep each error by its field too.","ar":"في النموذج الطويل، أضف قائمة قصيرة بالأخطاء في الأعلى، مع إبقاء كل خطأ بجوار حقله أيضًا."}$uxg$::jsonb),
  ($uxg$SK-P01-U05-01$uxg$, $uxg$P01-U05$uxg$, $uxg${"en":"Keep keyboard focus visible","ar":"أبقِ تركيز لوحة المفاتيح ظاهرًا"}$uxg$::jsonb, $uxg${"en":"Keep a clear focus ring on every field, button and link, so keyboard users see where they are.","ar":"أبقِ إطار تركيز (Focus ring) واضحًا على كل حقل وزر ورابط، ليعرف مستخدمو لوحة المفاتيح أين هم في الصفحة."}$uxg$::jsonb),
  ($uxg$SK-P01-U05-02$uxg$, $uxg$P01-U05$uxg$, $uxg${"en":"Make Tab follow the layout","ar":"اجعل Tab يتبع ترتيب الصفحة"}$uxg$::jsonb, $uxg${"en":"Order fields so Tab moves through them the way the page reads, top to bottom.","ar":"رتّب الحقول بحيث ينتقل Tab بينها كما تُقرأ الصفحة، من أعلى إلى أسفل."}$uxg$::jsonb),
  ($uxg$SK-P01-U05-03$uxg$, $uxg$P01-U05$uxg$, $uxg${"en":"Make every control reachable by keyboard","ar":"اجعل كل عنصر في متناول لوحة المفاتيح"}$uxg$::jsonb, $uxg${"en":"Build controls from real buttons, links and fields, so Tab reaches every one of them.","ar":"ابنِ العناصر من أزرار وروابط وحقول حقيقية، ليصل Tab إليها كلها."}$uxg$::jsonb),
  ($uxg$SK-P01-U05-04$uxg$, $uxg$P01-U05$uxg$, $uxg${"en":"Let people close pop-ups","ar":"دع الناس يغلقون النوافذ المنبثقة"}$uxg$::jsonb, $uxg${"en":"Give every pop-up a Close button that keyboard users can reach, and let Esc close it.","ar":"أعطِ كل نافذة منبثقة زر إغلاق يصل إليه مستخدمو لوحة المفاتيح، واجعل Esc يغلقها."}$uxg$::jsonb),
  ($uxg$SK-P01-U05-05$uxg$, $uxg$P01-U05$uxg$, $uxg${"en":"Make touch targets big and spaced","ar":"اجعل أهداف اللمس (Tap targets) كبيرة ومتباعدة"}$uxg$::jsonb, $uxg${"en":"Make each tap target at least 1 cm by 1 cm, with space between neighbours.","ar":"اجعل كل هدف لمس 1 سم × 1 سم على الأقل، مع مسافة بينه وبين ما يجاوره."}$uxg$::jsonb),
  ($uxg$SK-P01-U05-06$uxg$, $uxg$P01-U05$uxg$, $uxg${"en":"Don't put Clear next to Submit","ar":"لا تضع «مسح» بجوار «أرسل»"}$uxg$::jsonb, $uxg${"en":"Leave out Reset or Clear buttons that wipe a form, especially next to the submit button.","ar":"استغنِ عن أزرار «إعادة ضبط» (Reset) أو «مسح» التي تُفرغ النموذج، خاصة بجوار زر الإرسال."}$uxg$::jsonb),
  ($uxg$SK-P02-U01-01$uxg$, $uxg$P02-U01$uxg$, $uxg${"en":"Show the result of every action, right away","ar":"أظهِر نتيجة كل إجراء فورًا"}$uxg$::jsonb, $uxg${"en":"Give immediate, visible feedback when people act, and show progress (a spinner for a short wait, steps or a percentage for a long one) so they never wonder if it worked.","ar":"أظهِر ردًّا فوريًا (Feedback) على كل ما يفعله الناس، وأظهِر التقدّم (مؤشر دوّار لانتظار قصير، وخطوات أو نسبة لانتظار طويل) حتى لا يتساءلوا إن كان الإجراء قد نجح."}$uxg$::jsonb),
  ($uxg$SK-P02-U01-02$uxg$, $uxg$P02-U01$uxg$, $uxg${"en":"Tell people about changes that affect them","ar":"أخبِر الناس بالتغييرات التي تؤثر فيهم"}$uxg$::jsonb, $uxg${"en":"Never let something that matters to people change silently: say what changed, where it happened, and what they can do now.","ar":"لا تدَع شيئًا يهمّ الناس يتغيّر بصمت: قل ما الذي تغيّر، وأين حدث، وما الذي يستطيعون فعله الآن."}$uxg$::jsonb),
  ($uxg$SK-P02-U01-03$uxg$, $uxg$P02-U01$uxg$, $uxg${"en":"Use the words your users use","ar":"استخدم الكلمات التي يستخدمها مستخدموك"}$uxg$::jsonb, $uxg${"en":"Replace internal jargon, technical terms and unexplained abbreviations with the words people use for the same thing.","ar":"اكتب الكلمات التي يستخدمها الناس بدل المصطلحات الداخلية والتقنية والاختصارات غير المشروحة."}$uxg$::jsonb),
  ($uxg$SK-P02-U01-04$uxg$, $uxg$P02-U01$uxg$, $uxg${"en":"Follow the order and conventions people know","ar":"اتبع الترتيب والعادات المألوفة (Conventions) التي يعرفها الناس"}$uxg$::jsonb, $uxg${"en":"Organize information the way your users already do in their work and life, and keep familiar controls and symbols looking like what people expect.","ar":"رتّب المعلومات كما يرتّبها مستخدموك أصلًا في عملهم وحياتهم، واجعل العناصر والرموز المألوفة تبدو كما يتوقعها الناس."}$uxg$::jsonb),
  ($uxg$SK-P02-U02-01$uxg$, $uxg$P02-U02$uxg$, $uxg${"en":"Give a clear way out","ar":"أعطِ مخرجًا واضحًا"}$uxg$::jsonb, $uxg${"en":"Give every task, overlay and step a Cancel, Close or Back that is easy to find, clearly labelled, and quick to use.","ar":"أعطِ كل مهمة ونافذة وخطوة زر «إلغاء» أو «إغلاق» أو «رجوع» سهل الرؤية، واضح الاسم، وسريع الاستخدام."}$uxg$::jsonb),
  ($uxg$SK-P02-U02-02$uxg$, $uxg$P02-U02$uxg$, $uxg${"en":"Let people undo and go back where they expect","ar":"دَع الناس يتراجعون ويعودون إلى حيث يتوقعون"}$uxg$::jsonb, $uxg${"en":"Make Back return people one step, to exactly where they came from, and give a visible Undo for changes they may regret.","ar":"اجعل «رجوع» يعيد الناس خطوة واحدة، إلى المكان الذي جاؤوا منه بالضبط، وأعطِ «تراجع» ظاهرًا للتغييرات التي قد يندمون عليها."}$uxg$::jsonb),
  ($uxg$SK-P02-U02-03$uxg$, $uxg$P02-U02$uxg$, $uxg${"en":"Keep the same thing the same everywhere","ar":"اجعل الشيء الواحد بالشكل نفسه في كل مكان"}$uxg$::jsonb, $uxg${"en":"Use one word, one look and one place for the same action across every screen of a product.","ar":"استخدم كلمة واحدة وشكلًا واحدًا ومكانًا واحدًا للإجراء نفسه في كل شاشات المنتج."}$uxg$::jsonb),
  ($uxg$SK-P02-U02-04$uxg$, $uxg$P02-U02$uxg$, $uxg${"en":"Follow the conventions people bring from other products","ar":"اتبع العادات المألوفة (Conventions) التي يأتي بها الناس من منتجات أخرى"}$uxg$::jsonb, $uxg${"en":"Use the icons, controls and patterns people already know from other sites and apps, unless breaking them clearly helps the task.","ar":"استخدم الأيقونات والعناصر والأنماط التي يعرفها الناس أصلًا من مواقع وتطبيقات أخرى، إلا إذا كانت مخالفتها تساعد المهمة بوضوح."}$uxg$::jsonb),
  ($uxg$SK-P02-U03-01$uxg$, $uxg$P02-U03$uxg$, $uxg${"en":"Design out easy slips","ar":"صمّم بطريقة تمنع الزلّات (Slips) السهلة"}$uxg$::jsonb, $uxg${"en":"Prevent slips with helpful limits, good defaults and input formats that accept what people naturally type.","ar":"امنع الزلّات بحدود مفيدة، وقيم افتراضية جيدة، وصيغ إدخال تقبل ما يكتبه الناس عادةً."}$uxg$::jsonb),
  ($uxg$SK-P02-U03-02$uxg$, $uxg$P02-U03$uxg$, $uxg${"en":"Confirm only what's serious, and say exactly what will happen","ar":"لا تطلب التأكيد إلا للخطير، وقل بالضبط ما سيحدث"}$uxg$::jsonb, $uxg${"en":"Ask for confirmation only before actions with serious, lasting effects, and name what will happen on the dialog and its buttons.","ar":"اطلب التأكيد فقط قبل الإجراءات ذات الأثر الكبير الدائم، واذكر ما سيحدث في النافذة وعلى أزرارها."}$uxg$::jsonb),
  ($uxg$SK-P02-U03-03$uxg$, $uxg$P02-U03$uxg$, $uxg${"en":"Keep what people need in view","ar":"أبقِ ما يحتاجه الناس أمامهم"}$uxg$::jsonb, $uxg${"en":"Show the information people need at the moment they need it, instead of making them carry it in their heads from another screen or step.","ar":"اعرض المعلومات التي يحتاجها الناس في اللحظة التي يحتاجونها فيها، بدل أن تجبرهم على حفظها في أذهانهم من شاشة أو خطوة أخرى."}$uxg$::jsonb),
  ($uxg$SK-P02-U03-04$uxg$, $uxg$P02-U03$uxg$, $uxg${"en":"Let people pick instead of recall","ar":"دَع الناس يختارون بدل أن يتذكّروا"}$uxg$::jsonb, $uxg${"en":"Give options people can recognise: labels on icons, recent items, suggestions and visible menus.","ar":"أعطِ خيارات يتعرّف عليها الناس: أسماء على الأيقونات، وآخر ما استخدموه، واقتراحات، وقوائم ظاهرة."}$uxg$::jsonb),
  ($uxg$SK-P02-U04-01$uxg$, $uxg$P02-U04$uxg$, $uxg${"en":"Add shortcuts that don't get in the way","ar":"أضِف اختصارات لا تزعج أحدًا"}$uxg$::jsonb, $uxg${"en":"Give regular users faster ways to do frequent tasks, make them easy to discover, and keep the clear, slower path for beginners.","ar":"أعطِ المستخدمين المعتادين طرقًا أسرع للمهام المتكررة، واجعلها سهلة الاكتشاف، وأبقِ للمبتدئين الطريقة الواضحة وإن كانت أبطأ."}$uxg$::jsonb),
  ($uxg$SK-P02-U04-02$uxg$, $uxg$P02-U04$uxg$, $uxg${"en":"Let people repeat work in one go","ar":"دَع الناس يكرّرون العمل دفعة واحدة"}$uxg$::jsonb, $uxg${"en":"Let people act on many items at once, reuse what they did before, and automate predictable repeated tasks.","ar":"دَع الناس يتعاملون مع عناصر كثيرة مرة واحدة، ويعيدون استخدام ما فعلوه من قبل، ويجعلون المهام المتكررة المتوقعة تلقائية."}$uxg$::jsonb),
  ($uxg$SK-P02-U04-03$uxg$, $uxg$P02-U04$uxg$, $uxg${"en":"Cut what competes with the essentials","ar":"احذف ما ينافس الأساسيات"}$uxg$::jsonb, $uxg${"en":"Remove or move back information that is irrelevant or rarely needed, so what people need for the task stands out.","ar":"احذف المعلومات غير المهمة أو النادرة الاستخدام، أو أخّرها، حتى يبرز ما يحتاجه الناس للمهمة."}$uxg$::jsonb),
  ($uxg$SK-P02-U04-04$uxg$, $uxg$P02-U04$uxg$, $uxg${"en":"Keep everything the task needs","ar":"أبقِ كل ما تحتاجه المهمة"}$uxg$::jsonb, $uxg${"en":"Keep labels, signs and information people need for the task, even when a cleaner look tempts you to remove them.","ar":"أبقِ الأسماء والعلامات والمعلومات التي يحتاجها الناس للمهمة، حتى حين يغريك شكل أنظف بحذفها."}$uxg$::jsonb),
  ($uxg$SK-P02-U05-01$uxg$, $uxg$P02-U05$uxg$, $uxg${"en":"Write errors people understand and can fix","ar":"اكتب رسائل خطأ يفهمها الناس ويعرفون كيف يصلحونها"}$uxg$::jsonb, $uxg${"en":"Say what went wrong in plain words, precisely, without blame, and suggest a way to fix it.","ar":"قل ما الخطأ بكلمات بسيطة، وبدقة، ودون لوم، واقترح طريقة لإصلاحه."}$uxg$::jsonb),
  ($uxg$SK-P02-U05-02$uxg$, $uxg$P02-U05$uxg$, $uxg${"en":"Show errors where and when they help","ar":"أظهِر الأخطاء في المكان والوقت المناسبين"}$uxg$::jsonb, $uxg${"en":"Place the error next to its cause, make it noticeable, show it only once people are done, and keep what they typed.","ar":"ضع الخطأ بجانب سببه، واجعله ملحوظًا، وأظهِره فقط بعد أن ينتهي الناس، واحتفظ بما كتبوه."}$uxg$::jsonb),
  ($uxg$SK-P02-U05-03$uxg$, $uxg$P02-U05$uxg$, $uxg${"en":"Offer help at the moment it's needed","ar":"قدّم المساعدة في لحظة الحاجة"}$uxg$::jsonb, $uxg${"en":"Give short help in context, next to the task it's about, and make any tour or tip easy to skip.","ar":"قدّم مساعدة قصيرة في سياقها، بجانب المهمة التي تخصّها، واجعل أي جولة أو نصيحة سهلة التخطّي."}$uxg$::jsonb),
  ($uxg$SK-P02-U05-04$uxg$, $uxg$P02-U05$uxg$, $uxg${"en":"Make help easy to search and follow","ar":"اجعل المساعدة سهلة البحث والاتباع"}$uxg$::jsonb, $uxg${"en":"Organize help around people's tasks, make it searchable, and write it as short, concrete steps that are easy to scan.","ar":"نظّم المساعدة حول مهام الناس، واجعلها قابلة للبحث، واكتبها خطوات قصيرة محددة سهلة التصفّح."}$uxg$::jsonb),
  ($uxg$SK-P05-U01-01$uxg$, $uxg$P05-U01$uxg$, $uxg${"en":"Judge by the task, not the checklist","ar":"العبرة بإنجاز المهمة، لا بالـ Checklist"}$uxg$::jsonb, $uxg${"en":"Call a design accessible only when disabled people get the same content and features, and finish the task in a normal time.","ar":"لا تعتبر التصميم مناسبًا لذوي الإعاقة إلا إذا حصلوا على المحتوى والميزات نفسها، وأنهوا المهمة في وقت عادي."}$uxg$::jsonb),
  ($uxg$SK-P05-U01-02$uxg$, $uxg$P05-U01$uxg$, $uxg${"en":"Test with real users and their own tools","ar":"اختبر مع مستخدمين حقيقيين وبأدواتهم"}$uxg$::jsonb, $uxg${"en":"Test with disabled people on their own phones and assistive tools, instead of trusting a plugin, a seller's promise or an office phone.","ar":"اختبر مع أشخاص من ذوي الإعاقة على هواتفهم وبأدواتهم المساعدة (Assistive technology)، ولا تكتفِ بإضافة جاهزة أو وعد من شركة أو هاتف المكتب."}$uxg$::jsonb),
  ($uxg$SK-P05-U01-03$uxg$, $uxg$P05-U01$uxg$, $uxg${"en":"Let people jump straight to what they want","ar":"دع الناس يصلون مباشرة إلى ما يريدون"}$uxg$::jsonb, $uxg${"en":"Replace carousels, long pages and video-only help with links, a list of topics at the top, visible search and text people can jump to.","ar":"بدل الـ Carousel والصفحات الطويلة والشرح بالفيديو فقط، استخدم روابط، وقائمة مواضيع في أعلى الصفحة، وبحثًا ظاهرًا، ونصًا مكتوبًا يصل فيه الناس إلى ما يريدون مباشرة."}$uxg$::jsonb),
  ($uxg$SK-P05-U01-04$uxg$, $uxg$P05-U01$uxg$, $uxg${"en":"Accept input the way people type it","ar":"اقبل ما يكتبه الناس كما هو"}$uxg$::jsonb, $uxg${"en":"Accept spaces, dashes and real names, and let people type a value instead of forcing a hard-to-use picker.","ar":"اقبل المسافات والشرطات والأسماء الحقيقية، ودع الناس يكتبون القيمة بدل أداة اختيار صعبة."}$uxg$::jsonb),
  ($uxg$SK-P05-U01-05$uxg$, $uxg$P05-U01$uxg$, $uxg${"en":"Let people change text size and theme","ar":"دع الناس يغيّرون حجم الخط والمظهر (Theme)"}$uxg$::jsonb, $uxg${"en":"Let text follow the phone's text size, add a bigger-text button on reading screens, and offer dark mode without forcing it.","ar":"اجعل النص يتبع حجم الخط في الهاتف، وأضف زرًا لتكبير النص في شاشات القراءة، واترك الوضع الداكن اختيارًا لا إجبارًا."}$uxg$::jsonb),
  ($uxg$SK-P05-U02-01$uxg$, $uxg$P05-U02$uxg$, $uxg${"en":"Keep text dark enough to read","ar":"اجعل النص غامقًا بما يكفي للقراءة"}$uxg$::jsonb, $uxg${"en":"Give text at least 4.5:1 contrast with its background, or 3:1 when it's large or bold.","ar":"اجعل التباين بين النص وخلفيته 4.5:1 على الأقل، أو 3:1 إذا كان النص كبيرًا أو عريضًا."}$uxg$::jsonb),
  ($uxg$SK-P05-U02-02$uxg$, $uxg$P05-U02$uxg$, $uxg${"en":"Make things quieter without fading them","ar":"قلّل أهمية العنصر دون أن تجعله باهتًا"}$uxg$::jsonb, $uxg${"en":"Lower an element's importance with size, place or fewer items, not pale grey that looks disabled.","ar":"قلّل أهمية العنصر بالحجم أو المكان أو تقليل العناصر، لا باللون الرمادي الفاتح الذي يبدو معطّلًا."}$uxg$::jsonb),
  ($uxg$SK-P05-U02-03$uxg$, $uxg$P05-U02$uxg$, $uxg${"en":"Never use colour alone","ar":"لا تعتمد على اللون وحده"}$uxg$::jsonb, $uxg${"en":"Add a second sign to colour, like a word, an icon or a mark, and check the screen in grayscale.","ar":"أضف إلى اللون علامة ثانية، مثل كلمة أو أيقونة أو رمز، وافحص الشاشة بالأبيض والأسود."}$uxg$::jsonb),
  ($uxg$SK-P05-U02-04$uxg$, $uxg$P05-U02$uxg$, $uxg${"en":"Keep text on photos readable","ar":"اجعل النص فوق الصور سهل القراءة"}$uxg$::jsonb, $uxg${"en":"Darken the photo behind the text, and check it with the lightest photo that can appear.","ar":"اجعل الصورة أغمق خلف النص، وافحص النتيجة مع أفتح صورة يمكن أن تظهر."}$uxg$::jsonb),
  ($uxg$SK-P05-U02-05$uxg$, $uxg$P05-U02$uxg$, $uxg${"en":"Make dark mode readable","ar":"اجعل الوضع الداكن سهل القراءة"}$uxg$::jsonb, $uxg${"en":"In dark mode, use soft light colours instead of strong ones, and separate cards with a lighter fill.","ar":"في الوضع الداكن، استخدم ألوانًا فاتحة هادئة بدل الألوان القوية، وافصل البطاقات بلون أفتح."}$uxg$::jsonb),
  ($uxg$SK-P05-U03-01$uxg$, $uxg$P05-U03$uxg$, $uxg${"en":"Test it with the keyboard","ar":"اختبره بلوحة المفاتيح"}$uxg$::jsonb, $uxg${"en":"Put the mouse away and do the main task with Tab and Enter, checking you can see where you are, reach everything, and move in page order.","ar":"أبعِد الماوس وأنجز المهمة الأساسية بـ Tab وEnter، وتأكّد أنك ترى أين أنت، وتصل إلى كل شيء، وتتحرّك بترتيب الصفحة."}$uxg$::jsonb),
  ($uxg$SK-P05-U03-02$uxg$, $uxg$P05-U03$uxg$, $uxg${"en":"Restyle focus, never remove it","ar":"غيّر شكل التركيز، ولا تحذفه أبدًا"}$uxg$::jsonb, $uxg${"en":"Replace the default focus with a clear outline that fits the brand and shows on every background, not a colour change alone.","ar":"استبدل التركيز الافتراضي بإطار واضح يناسب الهوية ويظهر على كل خلفية، لا بتغيير اللون وحده."}$uxg$::jsonb),
  ($uxg$SK-P05-U03-03$uxg$, $uxg$P05-U03$uxg$, $uxg${"en":"Let people skip long menus","ar":"دع الناس يتخطّون القوائم الطويلة"}$uxg$::jsonb, $uxg${"en":"Add a \"Skip to main content\" link that appears when tabbing and lands on the main heading.","ar":"أضف رابط «انتقل إلى المحتوى الرئيسي» يظهر عند الضغط على Tab، ويُوصل إلى العنوان الرئيسي."}$uxg$::jsonb),
  ($uxg$SK-P05-U03-04$uxg$, $uxg$P05-U03$uxg$, $uxg${"en":"Make dropdowns work with keys","ar":"اجعل القوائم المنسدلة تعمل بالمفاتيح"}$uxg$::jsonb, $uxg${"en":"Let arrow keys move through options without picking, Enter pick, and a typed letter jump to matching options.","ar":"اجعل الأسهم تتنقّل بين الخيارات دون اختيار، وEnter يختار، والحرف المكتوب ينقلك إلى الخيارات التي تبدأ به."}$uxg$::jsonb),
  ($uxg$SK-P05-U03-05$uxg$, $uxg$P05-U03$uxg$, $uxg${"en":"Don't hide controls behind hover","ar":"لا تُخفِ العناصر خلف الـ Hover (مرور الماوس)"}$uxg$::jsonb, $uxg${"en":"Give hover menus and carousel controls a keyboard way in, like a clickable top-level page or buttons Tab can reach.","ar":"أعطِ قوائم الـ Hover وأزرار الـ Carousel طريقًا بلوحة المفاتيح، مثل رابط رئيسي يفتح صفحة كاملة، أو أزرار يصل إليها Tab."}$uxg$::jsonb),
  ($uxg$SK-P05-U04-01$uxg$, $uxg$P05-U04$uxg$, $uxg${"en":"Decide what an image needs","ar":"قرّر ماذا تحتاج الصورة"}$uxg$::jsonb, $uxg${"en":"Leave alt text empty for decorative images, say the action for clickable ones, and say the message for informative ones.","ar":"اترك النص البديل فارغًا للصور الزخرفية، واكتب الإجراء للصور القابلة للضغط، واكتب الرسالة للصور التي تحمل معلومة."}$uxg$::jsonb),
  ($uxg$SK-P05-U04-02$uxg$, $uxg$P05-U04$uxg$, $uxg${"en":"Write short, useful alt text","ar":"اكتب نصًا بديلًا قصيرًا ومفيدًا"}$uxg$::jsonb, $uxg${"en":"Keep alt text under about 150 characters, put the key words first, skip \"image of\", and don't repeat the caption.","ar":"اجعل النص البديل أقل من نحو 150 حرفًا، وضع الكلمات المهمة أولًا، ولا تكتب «صورة لـ»، ولا تكرّر التعليق المكتوب."}$uxg$::jsonb),
  ($uxg$SK-P05-U04-03$uxg$, $uxg$P05-U04$uxg$, $uxg${"en":"Give charts and big images a text version","ar":"أعطِ الرسوم البيانية والصور الكبيرة نسخة نصية"}$uxg$::jsonb, $uxg${"en":"Put the data of a chart, timetable or map on the page as text, and keep the alt text to its main point.","ar":"ضع بيانات الرسم البياني أو الجدول أو الخريطة في الصفحة كنص، واجعل النص البديل للفكرة الرئيسية فقط."}$uxg$::jsonb),
  ($uxg$SK-P05-U04-04$uxg$, $uxg$P05-U04$uxg$, $uxg${"en":"Write labels that make sense alone","ar":"اكتب تسميات (Labels) مفهومة وحدها"}$uxg$::jsonb, $uxg${"en":"Make each link and control say where it goes or what it does, with the key word first, never just \"Learn more\".","ar":"اجعل كل رابط وعنصر يقول إلى أين يذهب أو ماذا يفعل، والكلمة المهمة أولًا، لا «اعرف المزيد» فقط."}$uxg$::jsonb),
  ($uxg$SK-P05-U04-05$uxg$, $uxg$P05-U04$uxg$, $uxg${"en":"Move focus to what just opened","ar":"انقل التركيز إلى ما فُتح للتو"}$uxg$::jsonb, $uxg${"en":"When a menu or panel opens, move the screen reader's focus into it, so people know something happened.","ar":"حين تُفتح قائمة أو لوحة، انقل تركيز قارئ الشاشة إليها، ليعرف الناس أن شيئًا حدث."}$uxg$::jsonb),
  ($uxg$SK-P05-U05-01$uxg$, $uxg$P05-U05$uxg$, $uxg${"en":"Give every gesture a visible option","ar":"أعطِ كل إيماءة خيارًا ظاهرًا"}$uxg$::jsonb, $uxg${"en":"Put a visible button or menu next to any swipe, drag or long press, so people who can't see or do the gesture can still act.","ar":"ضع زرًا أو قائمة ظاهرة بجانب أي سحب أو جرّ أو ضغطة طويلة، ليستطيع من لا يرى الإيماءة أو لا يقدر عليها أن يُكمل."}$uxg$::jsonb),
  ($uxg$SK-P05-U05-02$uxg$, $uxg$P05-U05$uxg$, $uxg${"en":"Make slips easy to undo","ar":"اجعل التراجع عن الأخطاء سهلًا"}$uxg$::jsonb, $uxg${"en":"After an easy gesture deletes something, offer a clear Undo or ask first, and keep the item visible while people act on it.","ar":"حين تحذف إيماءة سهلة شيئًا، أعطِ زر تراجع واضحًا أو اسأل أولًا، وأبقِ العنصر ظاهرًا أثناء التعامل معه."}$uxg$::jsonb),
  ($uxg$SK-P05-U05-03$uxg$, $uxg$P05-U05$uxg$, $uxg${"en":"Respect \"Reduce motion\"","ar":"احترم إعداد «تقليل الحركة»"}$uxg$::jsonb, $uxg${"en":"Avoid flashing, and remove parallax, scroll effects and big moving animations when people turn on \"Reduce motion\".","ar":"تجنّب الوميض، وأزِل حركة الخلفية (Parallax) وتأثيرات التمرير والحركات الكبيرة حين يشغّل الناس «تقليل الحركة»."}$uxg$::jsonb),
  ($uxg$SK-P05-U05-04$uxg$, $uxg$P05-U05$uxg$, $uxg${"en":"Keep animations short","ar":"اجعل الحركات قصيرة"}$uxg$::jsonb, $uxg${"en":"Keep most animations between 100 and 500 ms, about 100 ms for small feedback, and never make people wait through one.","ar":"اجعل أغلب الحركات بين 100 و500 ms، ونحو 100 ms للاستجابات الصغيرة، ولا تجعل الناس ينتظرون انتهاء حركة."}$uxg$::jsonb),
  ($uxg$SK-P05-U05-05$uxg$, $uxg$P05-U05$uxg$, $uxg${"en":"Give people time to read","ar":"أعطِ الناس وقتًا ليقرؤوا"}$uxg$::jsonb, $uxg${"en":"Don't move content on its own, and don't let important messages vanish after a few seconds.","ar":"لا تجعل المحتوى يتحرّك وحده، ولا تجعل الرسائل المهمة تختفي بعد ثوانٍ."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-01$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Put the deciding facts first","ar":"ضع المعلومات الحاسمة أولًا"}$uxg$::jsonb, $uxg${"en":"Order a screen so the facts people decide with come before the main action and before any promotion.","ar":"رتّب الشاشة بحيث تأتي المعلومات التي يقرّر بها الناس قبل الإجراء الرئيسي وقبل أي ترويج."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-02$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Make no more than two things big","ar":"لا تكبّر أكثر من عنصرين"}$uxg$::jsonb, $uxg${"en":"Pick at most two elements to make big, and choose the ones people decide with.","ar":"اختر عنصرين على الأكثر لتكبيرهما، واختر ما يقرّر به الناس."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-03$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Lead text with what decides it","ar":"ابدأ النص بما يحسم القرار"}$uxg$::jsonb, $uxg${"en":"Pick or write text whose first words answer the question people came with.","ar":"اختر نصًا أو اكتبه بحيث تجيب كلماته الأولى عن السؤال الذي جاء به الناس."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-04$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Keep what most people need in view","ar":"أبقِ ما يحتاجه معظم الناس ظاهرًا"}$uxg$::jsonb, $uxg${"en":"Decide what stays on the screen and what goes behind a link, by how many people need it.","ar":"قرّر ما يبقى على الشاشة وما يذهب خلف رابط، حسب عدد من يحتاجونه."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-05$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Hide details in few, clearly named levels","ar":"أخفِ التفاصيل في مستويات قليلة بأسماء واضحة"}$uxg$::jsonb, $uxg${"en":"Name a link by what's behind it, keep to two levels, and keep things decided together on one screen.","ar":"سمِّ الرابط بما خلفه، ولا تتجاوز مستويين، وأبقِ ما يُقرَّر معًا في شاشة واحدة."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-06$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Don't make content look like an ad","ar":"لا تجعل المحتوى يشبه الإعلان"}$uxg$::jsonb, $uxg${"en":"Style and place real content so people don't take it for an ad and skip it.","ar":"صمّم المحتوى الحقيقي وضعه بحيث لا يظنّه الناس إعلانًا فيتخطّونه."}$uxg$::jsonb),
  ($uxg$SK-P10-U01-07$uxg$, $uxg$P10-U01$uxg$, $uxg${"en":"Use photos that carry information","ar":"استخدم صورًا تحمل معلومة"}$uxg$::jsonb, $uxg${"en":"Keep a photo when it shows what people need to decide or act, and drop it when it's decoration.","ar":"أبقِ الصورة عندما تُظهر ما يحتاجه الناس ليقرّروا أو يتصرّفوا، واحذفها إذا كانت للزينة فقط."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-01$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Use spacing to show what belongs together","ar":"استخدم المسافات لتُظهر العناصر المترابطة"}$uxg$::jsonb, $uxg${"en":"Set gaps so each label, price or button sits closer to its own item than to any other.","ar":"اضبط المسافات بحيث تكون كل تسمية أو سعر أو زر أقرب إلى عنصره من أي عنصر آخر."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-02$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Keep actions next to what they act on","ar":"ضع الإجراء بجانب ما يعمل عليه"}$uxg$::jsonb, $uxg${"en":"Place optional paths and buttons inside the group they belong to, not far away from it.","ar":"ضع الطرق الاختيارية والأزرار داخل المجموعة التي تخصّها، لا بعيدًا عنها."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-03$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Chunk into a few meaningful groups","ar":"قسّم المحتوى إلى مجموعات قليلة ذات معنى"}$uxg$::jsonb, $uxg${"en":"Split long content into a few titled groups, use space before borders, and check the groups with the squint test.","ar":"قسّم المحتوى الطويل إلى مجموعات قليلة بعناوين، واستخدم المسافات قبل الحدود، وتحقّق من المجموعات باختبار التحديق (Squint test)."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-04$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Make look-alikes and containers tell the truth","ar":"لا تجعل التشابه والحاويات توحي بعلاقة غير موجودة"}$uxg$::jsonb, $uxg${"en":"Use containers and matching styles only for things that really belong together.","ar":"استخدم الحاويات والأنماط المتشابهة فقط للعناصر المترابطة فعلًا."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-05$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Avoid false floors","ar":"تجنّب النهايات الوهمية (False floors)"}$uxg$::jsonb, $uxg${"en":"Make sure a page doesn't look finished before it ends, so people scroll to the rest.","ar":"تأكّد أن الصفحة لا تبدو منتهية قبل نهايتها، حتى يمرّر الناس إلى بقيّتها."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-06$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Code group names as real headings","ar":"اجعل أسماء المجموعات عناوين حقيقية"}$uxg$::jsonb, $uxg${"en":"Mark group names as headings in the code, not just big bold text, so screen-reader users can jump to them.","ar":"اجعل أسماء المجموعات عناوين (Headings) في الكود، لا مجرد نص كبير وعريض، حتى يقفز إليها مستخدمو قارئ الشاشة."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-07$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Build groups that stay whole when they stack","ar":"ابنِ مجموعات تبقى كاملة عند ترتيبها عموديًا"}$uxg$::jsonb, $uxg${"en":"Build each group as one block so it stays together when columns stack on a phone.","ar":"ابنِ كل مجموعة ككتلة واحدة حتى تبقى معًا عندما تُرتَّب الأعمدة فوق بعضها على الهاتف."}$uxg$::jsonb),
  ($uxg$SK-P10-U02-08$uxg$, $uxg$P10-U02$uxg$, $uxg${"en":"Pick a table or cards by the task","ar":"اختر الجدول أو البطاقات حسب المهمة"}$uxg$::jsonb, $uxg${"en":"Keep a comparison table on phones when people compare options, and use cards when they look at one at a time.","ar":"أبقِ جدول المقارنة على الهاتف عندما يقارن الناس بين الخيارات، واستخدم البطاقات عندما ينظرون إلى خيار واحد في كل مرة."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-01$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Give each button the emphasis its action needs","ar":"امنح كل زر البروز الذي يحتاجه إجراؤه"}$uxg$::jsonb, $uxg${"en":"Make the main action primary, less important ones secondary, and optional extras tertiary.","ar":"اجعل الإجراء الرئيسي Primary، والأقل أهمية Secondary، والإضافات الاختيارية Tertiary."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-02$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Let one thing lead","ar":"اجعل عنصرًا واحدًا هو الأبرز"}$uxg$::jsonb, $uxg${"en":"Save the accent color for the most important thing, and check with the squint test that it still leads.","ar":"احتفظ بلون التمييز (Accent color) لأهم عنصر، وتحقّق باختبار التحديق أنه ما زال الأبرز."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-03$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Set risky actions apart","ar":"افصل الإجراءات الخطرة"}$uxg$::jsonb, $uxg${"en":"Separate destructive actions from confirming ones with space and more than one visual signal.","ar":"افصل الإجراءات المدمّرة عن إجراءات التأكيد بالمسافة وبأكثر من إشارة بصرية."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-04$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Keep quiet text readable","ar":"أبقِ النص الهادئ مقروءًا"}$uxg$::jsonb, $uxg${"en":"Make secondary text quieter without going below 4.5:1 contrast, and cut clutter instead of fading it.","ar":"اجعل النص الثانوي أهدأ دون أن ينزل التباين (Contrast) عن 4.5:1، واحذف الزحام بدل أن تُبهته."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-05$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Know when large text may use 3:1","ar":"اعرف متى يكفي 3:1 للنص الكبير"}$uxg$::jsonb, $uxg${"en":"Apply 3:1 only to text that is 24px, or about 19px bold, and larger.","ar":"طبّق 3:1 فقط على النص بحجم 24px، أو نحو 19px بخط Bold، فما فوق."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-06$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Never rely on color alone","ar":"لا تعتمد على اللون وحده"}$uxg$::jsonb, $uxg${"en":"Add words, icons or shapes so the meaning survives without color, and check in grayscale.","ar":"أضف كلمات أو أيقونات أو أشكالًا حتى يبقى المعنى دون لون، وتحقّق بالأبيض والأسود."}$uxg$::jsonb),
  ($uxg$SK-P10-U03-07$uxg$, $uxg$P10-U03$uxg$, $uxg${"en":"Keep color meanings consistent","ar":"حافظ على ثبات معاني الألوان"}$uxg$::jsonb, $uxg${"en":"Use the link color only for links, and keep warning colors for warnings.","ar":"استخدم لون الروابط للروابط فقط، واحتفظ بألوان التحذير للتحذيرات."}$uxg$::jsonb),
  ($uxg$SK-P10-U04-01$uxg$, $uxg$P10-U04$uxg$, $uxg${"en":"Rearrange the layout at every width","ar":"أعد ترتيب التخطيط عند كل عرض"}$uxg$::jsonb, $uxg${"en":"Turn columns into one column, let rows wrap on narrow phones, and hand off how each breakpoint changes.","ar":"حوّل الأعمدة إلى عمود واحد، ودع الصفوف تلتفّ على الهواتف الضيّقة، ووضّح للمطوّرين كيف يتغيّر التخطيط عند كل نقطة تحوّل (Breakpoint)."}$uxg$::jsonb),
  ($uxg$SK-P10-U04-02$uxg$, $uxg$P10-U04$uxg$, $uxg${"en":"Put what people need first on a phone","ar":"ضع ما يحتاجه الناس أولًا على الهاتف"}$uxg$::jsonb, $uxg${"en":"Order the single column by what people need, not by how the wide columns sat.","ar":"رتّب العمود الواحد حسب ما يحتاجه الناس، لا حسب ترتيب الأعمدة العريضة."}$uxg$::jsonb),
  ($uxg$SK-P10-U04-03$uxg$, $uxg$P10-U04$uxg$, $uxg${"en":"Give the same information on every device","ar":"قدّم المعلومات نفسها على كل جهاز"}$uxg$::jsonb, $uxg${"en":"Hide or shrink only secondary items on small screens, never facts people need.","ar":"أخفِ أو صغّر العناصر الثانوية فقط على الشاشات الصغيرة، لا المعلومات التي يحتاجها الناس."}$uxg$::jsonb),
  ($uxg$SK-P10-U04-04$uxg$, $uxg$P10-U04$uxg$, $uxg${"en":"Keep related content together on wide screens","ar":"أبقِ المحتوى المترابط معًا على الشاشات العريضة"}$uxg$::jsonb, $uxg${"en":"When a layout grows, keep critical, related content in the same view instead of spreading it out.","ar":"عندما يتّسع التخطيط، أبقِ المحتوى المهم والمترابط في المساحة نفسها بدل أن تبعثره."}$uxg$::jsonb),
  ($uxg$SK-P10-U04-05$uxg$, $uxg$P10-U04$uxg$, $uxg${"en":"Check it's usable, not just that it fits","ar":"تحقّق أنه سهل الاستخدام، لا أنه يتّسع فقط"}$uxg$::jsonb, $uxg${"en":"Judge a narrow layout by whether people can still read and use it, not only by whether anything overflows.","ar":"احكم على التخطيط الضيّق بقدرة الناس على قراءته واستخدامه، لا بمجرد أن شيئًا لا يخرج عن الشاشة."}$uxg$::jsonb),
  ($uxg$SK-P10-U04-06$uxg$, $uxg$P10-U04$uxg$, $uxg${"en":"Fix the reading order in the code","ar":"صحّح ترتيب القراءة في الكود"}$uxg$::jsonb, $uxg${"en":"Put content in a code order that makes sense read aloud, with each label next to its value.","ar":"ضع المحتوى بترتيب في الكود يكون منطقيًا عند قراءته بصوت عالٍ، وكل تسمية بجانب قيمتها."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-01$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Let boxes grow with real text","ar":"دع الصناديق تكبر مع النص الحقيقي"}$uxg$::jsonb, $uxg${"en":"When long text doesn't fit, fix the container, not the words: let the text wrap and the box grow.","ar":"عندما لا يتّسع النص الطويل، أصلح الحاوية لا الكلمات: دع النص يلتفّ والصندوق يكبر."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-02$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Leave room for translated labels","ar":"اترك مساحة للتسميات المترجمة"}$uxg$::jsonb, $uxg${"en":"Size buttons and labels so a translation up to 50% longer still fits.","ar":"اضبط حجم الأزرار والتسميات بحيث تتّسع لترجمة أطول بنسبة تصل إلى 50%."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-03$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Design with real content","ar":"صمّم بمحتوى حقيقي"}$uxg$::jsonb, $uxg${"en":"Test layouts with real, longest-case text, and tighten wording only when every fact stays.","ar":"اختبر التخطيط بنصوص حقيقية وبأطول الحالات، واختصر الصياغة فقط عندما تبقى كل المعلومات."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-04$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Mirror the layout for Arabic","ar":"اعكس التخطيط للعربية"}$uxg$::jsonb, $uxg${"en":"Mirror direction-based patterns for right-to-left languages, and keep the whole screen consistent.","ar":"اعكس الأنماط المرتبطة بالاتجاه في اللغات التي تُكتب من اليمين إلى اليسار، وحافظ على اتساق الشاشة كلها."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-05$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Keep codes and numbers in their order","ar":"أبقِ الرموز والأرقام بترتيبها"}$uxg$::jsonb, $uxg${"en":"Don't mirror content such as codes and phone numbers: they keep their left-to-right order.","ar":"لا تعكس المحتوى مثل الرموز وأرقام الهواتف: فهي تحتفظ بترتيبها من اليسار إلى اليمين."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-06$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Answer critique with the design's goal","ar":"أجب عن النقد بهدف التصميم"}$uxg$::jsonb, $uxg${"en":"Reply to feedback by tying it to the screen's goal and a quick check, not to taste.","ar":"ردّ على الملاحظات بربطها بهدف الشاشة وباختبار سريع، لا بالذوق."}$uxg$::jsonb),
  ($uxg$SK-P10-U05-07$uxg$, $uxg$P10-U05$uxg$, $uxg${"en":"Write test tasks without clues","ar":"اكتب مهام اختبار بلا تلميحات"}$uxg$::jsonb, $uxg${"en":"Write a usability task as a situation with a checkable goal, without the screen's own labels.","ar":"اكتب مهمة اختبار الاستخدام (Usability test) كموقف بهدف يمكن التحقّق منه، دون أسماء عناصر الشاشة."}$uxg$::jsonb),
  ($uxg$SK-P10-U06-01$uxg$, $uxg$P10-U06$uxg$, $uxg${"en":"Watch what people do","ar":"راقب ما يفعله الناس"}$uxg$::jsonb, $uxg${"en":"Check a design by watching people use it, not by asking what they like or would do.","ar":"تحقّق من التصميم بمراقبة الناس وهم يستخدمونه، لا بسؤالهم عمّا يحبّونه أو ما سيفعلونه."}$uxg$::jsonb),
  ($uxg$SK-P10-U06-02$uxg$, $uxg$P10-U06$uxg$, $uxg${"en":"Define success before the test","ar":"حدّد النجاح قبل الاختبار"}$uxg$::jsonb, $uxg${"en":"Write down what counts as finishing each task, in checkable terms, before anyone tries it.","ar":"اكتب ما يُعدّ إنجازًا لكل مهمة، بشروط يمكن التحقّق منها، قبل أن يجرّبها أحد."}$uxg$::jsonb),
  ($uxg$SK-P10-U06-03$uxg$, $uxg$P10-U06$uxg$, $uxg${"en":"Test small, fix, test again","ar":"اختبر بعدد صغير، وأصلح، واختبر مجددًا"}$uxg$::jsonb, $uxg${"en":"Spend testing on several small rounds of about 5 people, with a fix between each round.","ar":"وزّع الاختبار على عدّة جولات صغيرة من نحو 5 أشخاص، مع إصلاح بين كل جولة والتي تليها."}$uxg$::jsonb),
  ($uxg$SK-P10-U06-04$uxg$, $uxg$P10-U06$uxg$, $uxg${"en":"Report small tests without percentages","ar":"اعرض نتائج الاختبارات الصغيرة بلا نِسَب مئوية"}$uxg$::jsonb, $uxg${"en":"Report a 5-person test as counts and reasons, not percentages that suggest false precision.","ar":"اعرض نتائج اختبار من 5 أشخاص كأعداد وأسباب، لا كنِسَب مئوية توحي بدقّة غير حقيقية."}$uxg$::jsonb),
  ($uxg$SK-P10-U06-05$uxg$, $uxg$P10-U06$uxg$, $uxg${"en":"Let people think aloud, without leading","ar":"دع الناس يفكّرون بصوت عالٍ، دون توجيه"}$uxg$::jsonb, $uxg${"en":"Ask people to think aloud while they work, and keep your words neutral so you don't steer them.","ar":"اطلب من الناس التفكير بصوت عالٍ أثناء العمل، وأبقِ كلماتك محايدة حتى لا توجّههم."}$uxg$::jsonb),
  ($uxg$SK-P12-U01-01$uxg$, $uxg$P12-U01$uxg$, $uxg${"en":"Start from the user's problem","ar":"ابدأ من مشكلة المستخدم"}$uxg$::jsonb, $uxg${"en":"Ask \"How might we solve this problem?\" before \"Can we use AI?\", and fix the real problem first.","ar":"اسأل «كيف يمكن أن نحلّ هذه المشكلة؟» (How might we) قبل «هل نستخدم الذكاء الاصطناعي؟»، وأصلح المشكلة الحقيقية أولًا."}$uxg$::jsonb),
  ($uxg$SK-P12-U01-02$uxg$, $uxg$P12-U01$uxg$, $uxg${"en":"Tell when AI beats a simple rule","ar":"اعرف متى يتفوّق الذكاء الاصطناعي على قاعدة بسيطة"}$uxg$::jsonb, $uxg${"en":"Use AI for personal suggestions, predictions, language and recognition, and a simple rule for fixed, predictable things.","ar":"استخدم الذكاء الاصطناعي للاقتراحات الشخصية والتوقّعات وفهم اللغة والتعرّف على الأشياء، وقاعدة بسيطة للأشياء الثابتة والمتوقّعة."}$uxg$::jsonb),
  ($uxg$SK-P12-U01-03$uxg$, $uxg$P12-U01$uxg$, $uxg${"en":"Choose to automate or to help","ar":"اختر بين الأتمتة (Automate) والمساعدة (Augment)"}$uxg$::jsonb, $uxg${"en":"Automate boring, repetitive tasks with a way to check them, and help people do tasks they enjoy, own or care about.","ar":"أتمِت المهام المملّة والمتكرّرة مع طريقة لمراجعتها، وساعد الناس في المهام التي يستمتعون بها أو يتحمّلون مسؤوليتها أو تهمّهم."}$uxg$::jsonb),
  ($uxg$SK-P12-U01-04$uxg$, $uxg$P12-U01$uxg$, $uxg${"en":"Weigh the two kinds of mistakes","ar":"وازن بين نوعي الأخطاء"}$uxg$::jsonb, $uxg${"en":"Decide whether a false alarm or a miss costs people more, and tune the AI against the worse one.","ar":"قرّر أيهما يكلّف الناس أكثر: الإنذار الكاذب (False positive) أم الحالة الفائتة (False negative)، واضبط الذكاء الاصطناعي ليتجنّب الأسوأ."}$uxg$::jsonb),
  ($uxg$SK-P12-U01-05$uxg$, $uxg$P12-U01$uxg$, $uxg${"en":"Choose fewer sure results or more complete ones","ar":"اختر بين نتائج قليلة مؤكّدة ونتائج كاملة"}$uxg$::jsonb, $uxg${"en":"Show a few sure results when misses cost little, and show every possible result when people can't afford to miss one.","ar":"اعرض نتائج قليلة مؤكّدة حين لا تكلّف الحالة الفائتة كثيرًا، واعرض كل النتائج الممكنة حين لا يحتمل الناس أن يفوتهم شيء."}$uxg$::jsonb),
  ($uxg$SK-P12-U02-01$uxg$, $uxg$P12-U02$uxg$, $uxg${"en":"Say what it can and can't do","ar":"قل ما يستطيعه وما لا يستطيعه"}$uxg$::jsonb, $uxg${"en":"State an AI feature's limits plainly the first time people meet it, with an example, and never promise magic.","ar":"اذكر حدود ميزة الذكاء الاصطناعي بوضوح من أول لقاء بها، مع مثال، ولا تَعِد بالسحر أبدًا."}$uxg$::jsonb),
  ($uxg$SK-P12-U02-02$uxg$, $uxg$P12-U02$uxg$, $uxg${"en":"Introduce it at the right moment","ar":"قدّمه في اللحظة المناسبة"}$uxg$::jsonb, $uxg${"en":"Show an AI feature when it's relevant, in a line or two, and offer a small safe way to try it.","ar":"أظهر ميزة الذكاء الاصطناعي حين تكون مفيدة، في سطر أو سطرين، وقدّم طريقة صغيرة آمنة لتجربتها."}$uxg$::jsonb),
  ($uxg$SK-P12-U02-03$uxg$, $uxg$P12-U02$uxg$, $uxg${"en":"Don't pretend it's a person","ar":"لا توهِم الناس أنه إنسان"}$uxg$::jsonb, $uxg${"en":"Make clear an assistant is automated, avoid human names and promises, and tell people what they can ask.","ar":"وضّح أن المساعد آلي، وتجنّب الأسماء والوعود البشرية، وأخبر الناس بما يمكنهم أن يطلبوه."}$uxg$::jsonb),
  ($uxg$SK-P12-U02-04$uxg$, $uxg$P12-U02$uxg$, $uxg${"en":"Explain the benefit, not the technology","ar":"اشرح الفائدة، لا التقنية"}$uxg$::jsonb, $uxg${"en":"Describe what an AI feature does for people, and keep technical details behind a \"How it works\" link.","ar":"صِف ما تفعله ميزة الذكاء الاصطناعي للناس، وضع التفاصيل التقنية في رابط «كيف يعمل»."}$uxg$::jsonb),
  ($uxg$SK-P12-U02-05$uxg$, $uxg$P12-U02$uxg$, $uxg${"en":"Say how it learns and changes","ar":"قل كيف يتعلّم ويتغيّر"}$uxg$::jsonb, $uxg${"en":"Tell people how their feedback helps, what it changes and when, and re-introduce a feature that changed.","ar":"أخبر الناس كيف يساعد رأيهم (Feedback)، وما الذي يغيّره ومتى، وعرّفهم من جديد بالميزة التي تغيّرت."}$uxg$::jsonb),
  ($uxg$SK-P12-U03-01$uxg$, $uxg$P12-U03$uxg$, $uxg${"en":"Give the reason that matters","ar":"اذكر السبب المهم"}$uxg$::jsonb, $uxg${"en":"Explain an AI result with the one reason people can check, right where and when they see it, without the full technical story.","ar":"اشرح نتيجة الذكاء الاصطناعي بالسبب الواحد الذي يستطيع الناس التأكّد منه، في مكانها ووقتها، دون القصة التقنية كاملة."}$uxg$::jsonb),
  ($uxg$SK-P12-U03-02$uxg$, $uxg$P12-U03$uxg$, $uxg${"en":"Say what data it uses, and what it doesn't know","ar":"قل ما البيانات التي يستخدمها، وما لا يعرفه"}$uxg$::jsonb, $uxg${"en":"Name the data behind a result, offer a way to stop using it, and admit when missing data means people should use their own judgment.","ar":"اذكر البيانات التي بُنيت عليها النتيجة، وقدّم طريقة لإيقاف استخدامها، واعترف حين تعني البيانات الناقصة أن على الناس استخدام تقديرهم."}$uxg$::jsonb),
  ($uxg$SK-P12-U03-03$uxg$, $uxg$P12-U03$uxg$, $uxg${"en":"Explain more when more is at stake","ar":"اشرح أكثر حين يكون الخطر أكبر"}$uxg$::jsonb, $uxg${"en":"Skip explanations for simple, low-risk results, and give the why and what to check when a wrong result could hurt health, money or safety.","ar":"تجاوز الشرح للنتائج البسيطة قليلة الخطر، واذكر السبب وما يجب مراجعته حين قد تضرّ نتيجة خطأ بالصحة أو المال أو السلامة."}$uxg$::jsonb),
  ($uxg$SK-P12-U03-04$uxg$, $uxg$P12-U03$uxg$, $uxg${"en":"Show confidence only if it helps decide","ar":"اعرض درجة الثقة فقط إذا ساعدت على القرار"}$uxg$::jsonb, $uxg${"en":"Leave out confidence scores that change no decision, avoid false precision, and never let a high number hide weak data.","ar":"احذف درجات الثقة التي لا تغيّر أي قرار، وتجنّب الدقة الزائفة، ولا تسمح أبدًا لرقم مرتفع أن يُخفي بيانات ضعيفة."}$uxg$::jsonb),
  ($uxg$SK-P12-U03-05$uxg$, $uxg$P12-U03$uxg$, $uxg${"en":"Show confidence people can act on","ar":"اعرض درجة الثقة (Confidence) بطريقة تساعد الناس على القرار"}$uxg$::jsonb, $uxg${"en":"Turn confidence into labels that say what to do next, and show the main options when the system is unsure.","ar":"حوّل درجة الثقة إلى عبارات تقول ماذا تفعل بعدها، واعرض الخيارات الأساسية حين لا يكون النظام متأكّدًا."}$uxg$::jsonb),
  ($uxg$SK-P12-U04-01$uxg$, $uxg$P12-U04$uxg$, $uxg${"en":"Let people fix it or switch it off","ar":"اسمح للناس بتصحيحه أو إيقافه"}$uxg$::jsonb, $uxg${"en":"Give every AI result a way to edit or undo it, offer an off switch from the start, and keep a manual way to do the task.","ar":"اجعل لكل نتيجة من الذكاء الاصطناعي طريقة لتعديلها أو التراجع عنها، وقدّم زر إيقاف من البداية، واحتفظ بطريقة يدوية لأداء المهمة."}$uxg$::jsonb),
  ($uxg$SK-P12-U04-02$uxg$, $uxg$P12-U04$uxg$, $uxg${"en":"Let people erase what it learned","ar":"اسمح للناس بمسح ما تعلّمه"}$uxg$::jsonb, $uxg${"en":"Let people remove or update past choices the AI learned from, or reset it, when their life or needs change.","ar":"اسمح للناس بحذف أو تحديث الاختيارات السابقة التي تعلّم منها الذكاء الاصطناعي، أو إعادة ضبطه، حين تتغيّر حياتهم أو احتياجاتهم."}$uxg$::jsonb),
  ($uxg$SK-P12-U04-03$uxg$, $uxg$P12-U04$uxg$, $uxg${"en":"Ask for feedback people can give","ar":"اطلب ملاحظات (Feedback) يسهل على الناس تقديمها"}$uxg$::jsonb, $uxg${"en":"Ask rarely and in the right tone, with simple options that don't overlap and match how people judge the result.","ar":"اسأل نادرًا وبالأسلوب المناسب، مع خيارات بسيطة لا تتداخل وتطابق طريقة حكم الناس على النتيجة."}$uxg$::jsonb),
  ($uxg$SK-P12-U04-04$uxg$, $uxg$P12-U04$uxg$, $uxg${"en":"Don't read too much into one action","ar":"لا تفسّر فعلًا واحدًا أكثر من اللازم"}$uxg$::jsonb, $uxg${"en":"Avoid treating a single tap, view or purchase as a wish for more, and ask what people meant when it's unclear.","ar":"تجنّب اعتبار ضغطة أو مشاهدة أو شراء واحد رغبةً في المزيد، واسأل الناس ماذا قصدوا حين لا يكون ذلك واضحًا."}$uxg$::jsonb),
  ($uxg$SK-P12-U04-05$uxg$, $uxg$P12-U04$uxg$, $uxg${"en":"Ask before you collect","ar":"اسأل قبل أن تجمع البيانات"}$uxg$::jsonb, $uxg${"en":"Tell people what behaviour data you collect and why, get permission up front, and show where they can see, edit or stop it.","ar":"أخبر الناس بنوع بيانات السلوك التي تجمعها ولماذا، وخذ إذنهم من البداية، ووضّح أين يستطيعون رؤيتها أو تعديلها أو إيقاف جمعها."}$uxg$::jsonb),
  ($uxg$SK-P12-U05-01$uxg$, $uxg$P12-U05$uxg$, $uxg${"en":"Say what failed and what to try","ar":"قل ما الذي فشل وما الذي يمكن تجربته"}$uxg$::jsonb, $uxg${"en":"Write AI error messages that name the limit plainly and tell people what input works, or another way to finish.","ar":"اكتب رسائل خطأ للذكاء الاصطناعي تذكر الحدّ بوضوح، وتقول للناس ما المدخلات التي تنجح، أو طريقة أخرى لإكمال المهمة."}$uxg$::jsonb),
  ($uxg$SK-P12-U05-02$uxg$, $uxg$P12-U05$uxg$, $uxg${"en":"Don't act on a guess","ar":"لا تتصرّف بناءً على تخمين"}$uxg$::jsonb, $uxg${"en":"Suggest instead of acting when the AI is unsure about someone's situation, and spot when a pattern has a reason the AI missed.","ar":"اقترح بدل أن تتصرّف حين لا يكون الذكاء الاصطناعي متأكّدًا من موقف الشخص، ولاحظ حين يكون للنمط سبب فاته الذكاء الاصطناعي."}$uxg$::jsonb),
  ($uxg$SK-P12-U05-03$uxg$, $uxg$P12-U05$uxg$, $uxg${"en":"Offer a safe next step","ar":"قدّم خطوة تالية آمنة"}$uxg$::jsonb, $uxg${"en":"When the AI can't give what people asked for, offer the closest useful option, and check it's safe when the stakes are high.","ar":"حين لا يستطيع الذكاء الاصطناعي تقديم ما طلبه الناس، قدّم أقرب خيار مفيد، وتأكّد أنه آمن حين يكون الخطر كبيرًا."}$uxg$::jsonb),
  ($uxg$SK-P12-U05-04$uxg$, $uxg$P12-U05$uxg$, $uxg${"en":"Hand back control with what people need","ar":"أعِد التحكّم مع ما يحتاجه الناس"}$uxg$::jsonb, $uxg${"en":"When the AI gives up, pass the task to the person or a human helper, with what's known, what's next, and how to do it.","ar":"حين يتوقّف الذكاء الاصطناعي، سلّم المهمة للشخص أو لموظّف، مع ما هو معروف، وما الخطوة التالية، وكيف تُنفَّذ."}$uxg$::jsonb),
  ($uxg$SK-P12-U05-05$uxg$, $uxg$P12-U05$uxg$, $uxg${"en":"Keep AI out of people's habits","ar":"أبعِد الذكاء الاصطناعي عن عادات الناس"}$uxg$::jsonb, $uxg${"en":"Keep the buttons people tap by habit in fixed places, put changing AI picks in their own area, and let people go back to a layout they know.","ar":"أبقِ الأزرار التي يضغط عليها الناس بحكم العادة في أماكن ثابتة، وضع اختيارات الذكاء الاصطناعي المتغيّرة في مساحة خاصة بها، واسمح للناس بالعودة إلى تصميم يعرفونه."}$uxg$::jsonb),
  ($uxg$SK-P13-U01-01$uxg$, $uxg$P13-U01$uxg$, $uxg${"en":"Treat AI output as a first draft","ar":"تعامل مع ناتج الذكاء الاصطناعي كمسوّدة أولى"}$uxg$::jsonb, $uxg${"en":"Use AI to get a first draft fast, then edit it and check every fact before anyone else sees it.","ar":"استخدم الذكاء الاصطناعي لتحصل على مسوّدة أولى بسرعة، ثم حرّرها وتحقّق من كل معلومة قبل أن يراها أحد."}$uxg$::jsonb),
  ($uxg$SK-P13-U01-02$uxg$, $uxg$P13-U01$uxg$, $uxg${"en":"Ask for many ideas, then pick","ar":"اطلب أفكارًا كثيرة، ثم اختر"}$uxg$::jsonb, $uxg${"en":"Ask for several very different versions, then use your own judgment to choose the few worth testing.","ar":"اطلب عدة نسخ مختلفة جدًا، ثم استخدم حكمك لتختار القليل الذي يستحق الاختبار."}$uxg$::jsonb),
  ($uxg$SK-P13-U01-03$uxg$, $uxg$P13-U01$uxg$, $uxg${"en":"Keep real users in the loop","ar":"لا تستغنِ عن المستخدمين الحقيقيين"}$uxg$::jsonb, $uxg${"en":"Use AI to prepare and organize research, but not to replace real people; AI-made respondents miss the less common answers.","ar":"استخدم الذكاء الاصطناعي لتجهيز البحث وتنظيمه، لا لاستبدال الناس الحقيقيين؛ فالمشاركون الذين يصنعهم الذكاء الاصطناعي تفوتهم الإجابات الأقل شيوعًا."}$uxg$::jsonb),
  ($uxg$SK-P13-U01-04$uxg$, $uxg$P13-U01$uxg$, $uxg${"en":"Check what AI learned from","ar":"انتبه لما تعلّم منه الذكاء الاصطناعي"}$uxg$::jsonb, $uxg${"en":"Spot answers shaped by mostly English, Western or simply wrong internet content, and fix them for your users.","ar":"اكتشف الإجابات المتأثّرة بمحتوى الإنترنت، وأغلبه إنجليزي وغربي أو خاطئ أحيانًا، وأصلحها لتناسب مستخدميك."}$uxg$::jsonb),
  ($uxg$SK-P13-U02-01$uxg$, $uxg$P13-U02$uxg$, $uxg${"en":"Give the AI context","ar":"أعطِ الذكاء الاصطناعي السياق"}$uxg$::jsonb, $uxg${"en":"Tell the AI about your product, your users and the exact situation, and leave out details that don't matter for the task.","ar":"أخبر الذكاء الاصطناعي عن منتجك ومستخدميك والموقف بالضبط، واترك التفاصيل التي لا تهمّ المهمة."}$uxg$::jsonb),
  ($uxg$SK-P13-U02-02$uxg$, $uxg$P13-U02$uxg$, $uxg${"en":"Make a specific ask","ar":"حدّد المطلوب بدقة"}$uxg$::jsonb, $uxg${"en":"Say what role the AI plays, what to produce, how many, in which steps and in what format.","ar":"حدّد الدور الذي يقوم به الذكاء الاصطناعي، وماذا ينتج، وكم نسخة، وبأي خطوات، وبأي شكل."}$uxg$::jsonb),
  ($uxg$SK-P13-U02-03$uxg$, $uxg$P13-U02$uxg$, $uxg${"en":"Add rules and examples","ar":"أضف قواعد وأمثلة"}$uxg$::jsonb, $uxg${"en":"Give limits, tone and guidelines, plus good and bad examples, so the AI knows what you want and what to avoid.","ar":"أعطِ حدودًا ونبرة وإرشادات، مع أمثلة جيدة وسيئة، حتى يعرف الذكاء الاصطناعي ما تريده وما يجب أن يتجنّبه."}$uxg$::jsonb),
  ($uxg$SK-P13-U02-04$uxg$, $uxg$P13-U02$uxg$, $uxg${"en":"Check and refine the result","ar":"راجع النتيجة وحسّنها"}$uxg$::jsonb, $uxg${"en":"Check that every instruction was followed, ask again with what's missing, combine the best parts with your own, and skip AI when doing it yourself is faster.","ar":"تحقّق من تنفيذ كل تعليمة، واطلب مرة أخرى بما ينقص، واجمع أفضل الأجزاء مع عملك، واترك الذكاء الاصطناعي حين يكون عملك بنفسك أسرع."}$uxg$::jsonb),
  ($uxg$SK-P13-U03-01$uxg$, $uxg$P13-U03$uxg$, $uxg${"en":"Catch made-up facts","ar":"اكتشف المعلومات المُختلَقة (Hallucinations)"}$uxg$::jsonb, $uxg${"en":"Expect confident but false facts and fake sources, and check every fact at its original source before you use it.","ar":"توقّع معلومات خاطئة تُقال بثقة ومصادر مزيّفة، وتحقّق من كل معلومة في مصدرها الأصلي قبل أن تستخدمها."}$uxg$::jsonb),
  ($uxg$SK-P13-U03-02$uxg$, $uxg$P13-U03$uxg$, $uxg${"en":"Don't let AI just agree with you","ar":"لا تدع الذكاء الاصطناعي يوافقك فقط"}$uxg$::jsonb, $uxg${"en":"Ask without giving your opinion, start a new chat for a fresh view, and don't trust an answer that flips when you push back.","ar":"اسأل دون أن تذكر رأيك، وابدأ محادثة جديدة لرأي لم يتأثّر بكلامك، ولا تثق بإجابة تنقلب حين تعترض."}$uxg$::jsonb),
  ($uxg$SK-P13-U03-03$uxg$, $uxg$P13-U03$uxg$, $uxg${"en":"Treat AI reviews as leads","ar":"تعامل مع مراجعات الذكاء الاصطناعي كمؤشّرات"}$uxg$::jsonb, $uxg${"en":"Use AI design reviews as leads to check, knowing some suggestions are wrong and deeper problems are often missed.","ar":"استخدم مراجعات التصميم من الذكاء الاصطناعي كمؤشّرات تتحقّق منها، وأنت تعرف أن بعض اقتراحاتها خاطئة وأن المشكلات الأعمق تفوتها غالبًا."}$uxg$::jsonb),
  ($uxg$SK-P13-U03-04$uxg$, $uxg$P13-U03$uxg$, $uxg${"en":"Judge AI on many answers, not one","ar":"قيّم الذكاء الاصطناعي بإجابات كثيرة، لا بواحدة"}$uxg$::jsonb, $uxg${"en":"Test an AI tool or feature with many real inputs, several times each, before you trust it.","ar":"اختبر أداة أو ميزة ذكاء اصطناعي بمدخلات حقيقية كثيرة، وعدة مرات لكل منها، قبل أن تثق بها."}$uxg$::jsonb),
  ($uxg$SK-P13-U04-01$uxg$, $uxg$P13-U04$uxg$, $uxg${"en":"Plan studies with AI, then review","ar":"خطّط الدراسات بالذكاء الاصطناعي، ثم راجع"}$uxg$::jsonb, $uxg${"en":"Let AI draft tasks, questions and study documents from your template, then fix leading wording and filled-in mistakes.","ar":"دع الذكاء الاصطناعي يكتب مسوّدات المهام والأسئلة ومستندات الدراسة من قالبك، ثم أصلح الصياغة الموجِّهة والأخطاء في البيانات المملوءة."}$uxg$::jsonb),
  ($uxg$SK-P13-U04-02$uxg$, $uxg$P13-U04$uxg$, $uxg${"en":"Watch what users do","ar":"راقب ما يفعله المستخدمون"}$uxg$::jsonb, $uxg${"en":"Don't let AI analyze usability tests from transcripts or notes alone; it can't see what users do.","ar":"لا تدع الذكاء الاصطناعي يحلّل اختبارات قابلية الاستخدام من النصوص أو الملاحظات وحدها؛ فهو لا يرى ما يفعله المستخدمون."}$uxg$::jsonb),
  ($uxg$SK-P13-U04-03$uxg$, $uxg$P13-U04$uxg$, $uxg${"en":"Treat AI themes as a first pass","ar":"تعامل مع مجموعات الذكاء الاصطناعي (Themes) كخطوة أولى"}$uxg$::jsonb, $uxg${"en":"Use AI groupings and summaries to start analysis, then review them against the data and its context.","ar":"استخدم تجميعات الذكاء الاصطناعي وملخّصاته لتبدأ التحليل، ثم راجعها على البيانات وسياقها."}$uxg$::jsonb),
  ($uxg$SK-P13-U04-04$uxg$, $uxg$P13-U04$uxg$, $uxg${"en":"Spot-check transcripts and cleaned data","ar":"افحص عيّنات من النصوص والبيانات المنظّفة"}$uxg$::jsonb, $uxg${"en":"Check AI transcripts, translations and removed personal data against the original, especially for Arabic dialects and quotes you'll use.","ar":"قارن نصوص الذكاء الاصطناعي وترجماته والبيانات الشخصية المحذوفة بالأصل، خاصة في اللهجات العربية والاقتباسات التي ستستخدمها."}$uxg$::jsonb),
  ($uxg$SK-P13-U05-01$uxg$, $uxg$P13-U05$uxg$, $uxg${"en":"Give AI the small jobs","ar":"أعطِ الذكاء الاصطناعي المهام الصغيرة"}$uxg$::jsonb, $uxg${"en":"Use AI for narrow, repetitive design tasks, like renaming layers or drafting placeholder text, not for whole products.","ar":"استخدم الذكاء الاصطناعي في مهام التصميم المحدودة والمتكرّرة، مثل إعادة تسمية الطبقات أو كتابة نصوص مؤقتة، لا في منتجات كاملة."}$uxg$::jsonb),
  ($uxg$SK-P13-U05-02$uxg$, $uxg$P13-U05$uxg$, $uxg${"en":"Treat AI screens as ideas","ar":"تعامل مع شاشات الذكاء الاصطناعي كأفكار"}$uxg$::jsonb, $uxg${"en":"Use generated layouts for ideas, spot clutter, repeats and wrong emphasis, and judge usability, not polish.","ar":"استخدم التصاميم المولَّدة كأفكار، واكتشف الزحام والتكرار والتركيز الخاطئ، واحكم على قابلية الاستخدام لا على الشكل الأنيق."}$uxg$::jsonb),
  ($uxg$SK-P13-U05-03$uxg$, $uxg$P13-U05$uxg$, $uxg${"en":"Write specific design prompts","ar":"اكتب طلبات تصميم محدّدة"}$uxg$::jsonb, $uxg${"en":"Name a clear visual style, attach a simple reference, give real content, and don't ask AI to copy a famous brand.","ar":"سمِّ أسلوبًا بصريًا واضحًا، وأرفق مرجعًا بسيطًا، وأعطِ محتوى حقيقيًا، ولا تطلب من الذكاء الاصطناعي تقليد علامة تجارية مشهورة."}$uxg$::jsonb),
  ($uxg$SK-P13-U05-04$uxg$, $uxg$P13-U05$uxg$, $uxg${"en":"Feed prototypes realistic data","ar":"ضع في النماذج الأولية بيانات واقعية"}$uxg$::jsonb, $uxg${"en":"Have AI make mock data that fits your users, formats and test tasks, without pasting sensitive real data into it.","ar":"اطلب من الذكاء الاصطناعي بيانات تجريبية (Mock data) تناسب مستخدميك والصيغ المعتادة عندهم ومهام اختبارك، دون أن تلصق فيه بيانات حقيقية حسّاسة."}$uxg$::jsonb),
  ($uxg$SK-P14-U01-01$uxg$, $uxg$P14-U01$uxg$, $uxg${"en":"Block the screen only when the task needs it","ar":"لا تحجب الشاشة إلا حين تحتاجه المهمة"}$uxg$::jsonb, $uxg${"en":"Use a modal dialog for a critical warning or for information the current task can't continue without, and never for unrelated offers, least of all in checkout.","ar":"استخدم الـ Modal dialog لتحذير مهم أو لمعلومة لا تكتمل المهمة الحالية دونها، ولا تستخدمه أبدًا لعروض لا علاقة لها بالمهمة، وخاصة أثناء الدفع."}$uxg$::jsonb),
  ($uxg$SK-P14-U01-02$uxg$, $uxg$P14-U01$uxg$, $uxg${"en":"Keep decisions that need more information out of a modal","ar":"أبعِد القرارات التي تحتاج معلومات أكثر عن الـ Modal"}$uxg$::jsonb, $uxg${"en":"Move a decision out of a modal dialog when people need to check information the modal hides.","ar":"انقل القرار خارج الـ Modal dialog حين يحتاج الناس إلى مراجعة معلومات يُخفيها."}$uxg$::jsonb),
  ($uxg$SK-P14-U01-03$uxg$, $uxg$P14-U01$uxg$, $uxg${"en":"Keep bottom sheets short, single and easy to close","ar":"اجعل الـ Bottom sheet قصيرًا ومنفردًا وسهل الإغلاق"}$uxg$::jsonb, $uxg${"en":"Use a bottom sheet for a quick task, never stack sheets or put a long flow in one, and give it a Close button that Back also respects.","ar":"استخدم الـ Bottom sheet لمهمة سريعة، ولا تكدّس الـ Sheets ولا تضع فيه خطوات كثيرة، وأعطه زر إغلاق، واجعل زر الرجوع يغلقه أيضًا."}$uxg$::jsonb),
  ($uxg$SK-P14-U01-04$uxg$, $uxg$P14-U01$uxg$, $uxg${"en":"Put only extra help in a tooltip","ar":"لا تضع في الـ Tooltip إلا مساعدة إضافية"}$uxg$::jsonb, $uxg${"en":"Keep what people need to finish a task on the screen, and use a tooltip only for brief, useful extra help that works without a mouse.","ar":"أبقِ ما يحتاجه الناس لإنهاء المهمة ظاهرًا على الشاشة، واستخدم الـ Tooltip فقط لمساعدة إضافية قصيرة ومفيدة تعمل دون فأرة."}$uxg$::jsonb),
  ($uxg$SK-P14-U01-05$uxg$, $uxg$P14-U01$uxg$, $uxg${"en":"Match the message to how much it matters","ar":"اجعل الرسالة على قدر أهميتها"}$uxg$::jsonb, $uxg${"en":"Use a snackbar for low-priority news that needs no action, a banner for something that stays until it's resolved, and a dialog only when people must respond now.","ar":"استخدم الـ Snackbar لخبر قليل الأهمية لا يحتاج إجراءً، والـ Banner لشيء يبقى حتى يُحلّ، والـ Dialog فقط حين يجب أن يردّ الناس الآن."}$uxg$::jsonb),
  ($uxg$SK-P14-U02-01$uxg$, $uxg$P14-U02$uxg$, $uxg${"en":"Collapse only what most people skip","ar":"لا تطوِ إلا ما يتخطّاه أغلب الناس"}$uxg$::jsonb, $uxg${"en":"Use an accordion when people need only a few sections of a long page, and show everything when they need most of it.","ar":"استخدم الـ Accordion حين يحتاج الناس أقسامًا قليلة من صفحة طويلة، واعرض كل شيء حين يحتاجون أغلبه."}$uxg$::jsonb),
  ($uxg$SK-P14-U02-02$uxg$, $uxg$P14-U02$uxg$, $uxg${"en":"Never collapse what people must see","ar":"لا تطوِ أبدًا ما يجب أن يراه الناس"}$uxg$::jsonb, $uxg${"en":"Keep a fee, a deadline or a warning outside closed panels, so nobody misses it.","ar":"أبقِ الرسوم أو الموعد النهائي أو التحذير خارج الأقسام المطويّة، حتى يراها الجميع."}$uxg$::jsonb),
  ($uxg$SK-P14-U02-03$uxg$, $uxg$P14-U02$uxg$, $uxg${"en":"Make one action stand out","ar":"اجعل إجراءً واحدًا هو الأوضح"}$uxg$::jsonb, $uxg${"en":"Give the main action of an area its own filled style and keep the other actions quieter, so people see at once which button moves them forward.","ar":"أعطِ الإجراء الرئيسي في كل منطقة شكلًا ممتلئًا خاصًا به، واجعل باقي الإجراءات أهدأ، حتى يرى الناس فورًا أيّ زر ينقلهم إلى الخطوة التالية."}$uxg$::jsonb),
  ($uxg$SK-P14-U02-04$uxg$, $uxg$P14-U02$uxg$, $uxg${"en":"Keep frequent actions in sight","ar":"أبقِ الإجراءات المتكرّرة ظاهرة"}$uxg$::jsonb, $uxg${"en":"Show the actions people use often directly on the screen, and move rare, low-priority ones into a menu.","ar":"اعرض الإجراءات التي يستخدمها الناس كثيرًا على الشاشة مباشرة، وانقل الإجراءات النادرة وقليلة الأهمية إلى قائمة."}$uxg$::jsonb),
  ($uxg$SK-P14-U02-05$uxg$, $uxg$P14-U02$uxg$, $uxg${"en":"Float only the screen's main action","ar":"لا تعطِ الزر العائم إلا للإجراء الرئيسي في الشاشة"}$uxg$::jsonb, $uxg${"en":"Use one floating action button for the most common and important action on a screen, and give it a text label when its icon could be unclear.","ar":"استخدم Floating action button واحدًا للإجراء الأكثر استخدامًا وأهمية في الشاشة، وأعطِه تسمية نصية حين قد تكون أيقونته غير واضحة."}$uxg$::jsonb),
  ($uxg$SK-P14-U02-06$uxg$, $uxg$P14-U02$uxg$, $uxg${"en":"Use chips for a group of related choices","ar":"استخدم الـ Chips لمجموعة من الاختيارات المترابطة"}$uxg$::jsonb, $uxg${"en":"Show related small choices in one area as a row of chips (filters, entered items, suggestions, quick actions), make entered chips removable, and keep a single main step like Save or Post as a button.","ar":"اعرض الاختيارات الصغيرة المترابطة في مكان واحد في صفّ من الـ Chips (فلاتر، أو عناصر مُدخلة، أو اقتراحات، أو إجراءات سريعة)، واجعل الـ Chips المُدخلة قابلة للحذف، وأبقِ الخطوة الرئيسية الواحدة مثل «حفظ» أو «انشر» زرًا."}$uxg$::jsonb),
  ($uxg$SK-P14-U03-01$uxg$, $uxg$P14-U03$uxg$, $uxg${"en":"Suggest only searches that find something","ar":"لا تقترح إلا عمليات بحث تجد شيئًا"}$uxg$::jsonb, $uxg${"en":"Offer a search suggestion only when it leads to good, relevant results.","ar":"لا تعرض اقتراح بحث إلا إذا كان يوصل إلى نتائج جيدة ومرتبطة بما يبحث عنه الناس."}$uxg$::jsonb),
  ($uxg$SK-P14-U03-02$uxg$, $uxg$P14-U03$uxg$, $uxg${"en":"Show what the suggestion adds","ar":"وضّح ما يضيفه الاقتراح"}$uxg$::jsonb, $uxg${"en":"Style the suggested part differently from what people typed: highlight the added words when suggestions complete the query, and the typed words when they can appear anywhere.","ar":"اجعل شكل الجزء المقترح مختلفًا عمّا كتبه الناس: أبرز الكلمات المضافة حين تُكمل الاقتراحات ما كُتب، وأبرز الكلمات المكتوبة حين قد تظهر في أي مكان."}$uxg$::jsonb),
  ($uxg$SK-P14-U03-03$uxg$, $uxg$P14-U03$uxg$, $uxg${"en":"Turn no results into a next step","ar":"حوّل «لا توجد نتائج» إلى خطوة تالية"}$uxg$::jsonb, $uxg${"en":"Say clearly that nothing matched, offer ways forward like a spelling fix, similar searches or fewer words, and keep the tone plain, never mocking.","ar":"قل بوضوح إنه لا توجد نتائج، واعرض خطوات تالية مثل تصحيح الإملاء أو عمليات بحث مشابهة أو كلمات أقل، وأبقِ الأسلوب بسيطًا، دون سخرية أبدًا."}$uxg$::jsonb),
  ($uxg$SK-P14-U03-04$uxg$, $uxg$P14-U03$uxg$, $uxg${"en":"Name filters so people can predict them","ar":"سمِّ الفلاتر بحيث يتوقّع الناس محتواها"}$uxg$::jsonb, $uxg${"en":"Use filter categories and values that people can understand and predict: no vague labels, no internal codes or jargon.","ar":"استخدم فئات وقيم فلاتر يفهمها الناس ويتوقّعون محتواها: بدون أسماء مبهمة، وبدون رموز داخلية أو مصطلحات صعبة."}$uxg$::jsonb),
  ($uxg$SK-P14-U03-05$uxg$, $uxg$P14-U03$uxg$, $uxg${"en":"Offer the filters people need, in their order","ar":"قدّم الفلاتر التي يحتاجها الناس، بترتيب أهميتها لهم"}$uxg$::jsonb, $uxg${"en":"Cover the aspects people really filter by, and put the most general and most used categories first.","ar":"غطِّ الجوانب التي يفلتر بها الناس فعلًا، وضع الفئات الأعمّ والأكثر استخدامًا أولًا."}$uxg$::jsonb),
  ($uxg$SK-P14-U04-01$uxg$, $uxg$P14-U04$uxg$, $uxg${"en":"Keep the standard look and layout","ar":"حافظ على الشكل والترتيب المعتادين"}$uxg$::jsonb, $uxg${"en":"Use square checkboxes and round radio buttons, one choice per line, with the whole row tappable.","ar":"استخدم Checkbox مربعًا وRadio button دائريًا، واختيارًا واحدًا في كل سطر، واجعل السطر كله قابلًا للضغط."}$uxg$::jsonb),
  ($uxg$SK-P14-U04-02$uxg$, $uxg$P14-U04$uxg$, $uxg${"en":"Word choices so they read at a glance","ar":"اكتب الاختيارات بحيث تُفهم بنظرة واحدة"}$uxg$::jsonb, $uxg${"en":"Write positive, active labels that say what turning the choice on does, short enough to read at a glance.","ar":"اكتب أسماء إيجابية تقول ما يحدث حين تختار الخيار، وقصيرة بحيث تُقرأ بنظرة واحدة."}$uxg$::jsonb),
  ($uxg$SK-P14-U04-03$uxg$, $uxg$P14-U04$uxg$, $uxg${"en":"Give radio buttons a complete set and a start","ar":"اجعل الـ Radio buttons كاملة، وابدأ باختيار"}$uxg$::jsonb, $uxg${"en":"Cover every answer people may have, with \"Other\" or \"None\" when needed, and start with one choice selected.","ar":"غطِّ كل إجابة قد تكون عند الناس، وأضف «أخرى» أو «لا شيء» عند الحاجة، وابدأ باختيار واحد محدَّد."}$uxg$::jsonb),
  ($uxg$SK-P14-U04-04$uxg$, $uxg$P14-U04$uxg$, $uxg${"en":"Match the control to when the change happens","ar":"اختر العنصر بحسب وقت حدوث التغيير"}$uxg$::jsonb, $uxg${"en":"Use a toggle only for a change that happens the moment it's flipped; use checkboxes and radio buttons for settings that a button applies, and a button for actions.","ar":"استخدم الـ Toggle فقط لتغيير يحدث لحظة الضغط عليه؛ واستخدم الـ Checkbox والـ Radio button لإعدادات يطبّقها زر، واستخدم زرًا للإجراءات."}$uxg$::jsonb),
  ($uxg$SK-P14-U04-05$uxg$, $uxg$P14-U04$uxg$, $uxg${"en":"Make a toggle's state unmistakable","ar":"اجعل حالة الـ Toggle واضحة بلا لبس"}$uxg$::jsonb, $uxg${"en":"Show whether a toggle is on or off without a lone state word that reads like its label: name the setting, and show both Off and On if you show either.","ar":"وضّح هل الـ Toggle يعمل أم لا، دون كلمة حالة وحيدة تُقرأ كأنها اسمه: اكتب اسم الإعداد، وإن كتبت كلمة حالة فاكتب الكلمتين «إيقاف» و«تشغيل»."}$uxg$::jsonb),
  ($uxg$SK-P14-U05-01$uxg$, $uxg$P14-U05$uxg$, $uxg${"en":"Ask only for what you need","ar":"اطلب ما تحتاجه فقط"}$uxg$::jsonb, $uxg${"en":"Cut every field the task doesn't need now, or that the product can get another way or later.","ar":"احذف كل حقل لا تحتاجه المهمة الآن، أو يمكن للمنتج أن يحصل عليه بطريقة أخرى أو في وقت لاحق."}$uxg$::jsonb),
  ($uxg$SK-P14-U05-02$uxg$, $uxg$P14-U05$uxg$, $uxg${"en":"Lay fields out in one clear path","ar":"رتّب الحقول في اتجاه واحد واضح"}$uxg$::jsonb, $uxg${"en":"Use one column, keep each label next to its own field, and order fields the way people find the information.","ar":"استخدم عمودًا واحدًا، وضع اسم كل حقل بجانب حقله، ورتّب الحقول بالترتيب الذي يجد به الناس المعلومات."}$uxg$::jsonb),
  ($uxg$SK-P14-U05-03$uxg$, $uxg$P14-U05$uxg$, $uxg${"en":"Keep labels in view","ar":"اجعل أسماء الحقول ظاهرة دائمًا"}$uxg$::jsonb, $uxg${"en":"Put a visible label outside each field instead of placeholder text that disappears when people type.","ar":"ضع اسمًا ظاهرًا خارج كل حقل، بدل نص Placeholder يختفي حين يبدأ الناس الكتابة."}$uxg$::jsonb),
  ($uxg$SK-P14-U05-04$uxg$, $uxg$P14-U05$uxg$, $uxg${"en":"Say what each field needs","ar":"وضّح ما يحتاجه كل حقل"}$uxg$::jsonb, $uxg${"en":"Mark required and optional fields, state format rules before people type, and match the control to the answer.","ar":"ميّز الحقول المطلوبة والاختيارية، واذكر شروط الإدخال قبل أن يكتب الناس، واختر العنصر المناسب للإجابة."}$uxg$::jsonb),
  ($uxg$SK-P14-U05-05$uxg$, $uxg$P14-U05$uxg$, $uxg${"en":"Make errors and exits safe","ar":"اجعل الأخطاء والخروج آمنين"}$uxg$::jsonb, $uxg${"en":"Show specific errors next to the field with more than colour, keep what people typed, and leave out Reset buttons.","ar":"اعرض رسالة خطأ محددة بجانب الحقل، بأكثر من اللون، واحتفظ بما كتبه الناس، ولا تضع زر Reset."}$uxg$::jsonb),
  ($uxg$SK-P14-U06-01$uxg$, $uxg$P14-U06$uxg$, $uxg${"en":"Use a stepper for small counts","ar":"استخدم الـ Stepper للأعداد الصغيرة"}$uxg$::jsonb, $uxg${"en":"Pick a stepper when most people choose one common value and change it by a little, and start it on that value.","ar":"اختر الـ Stepper حين يختار أغلب الناس قيمة شائعة واحدة ويغيّرونها قليلًا، وابدأه على هذه القيمة."}$uxg$::jsonb),
  ($uxg$SK-P14-U06-02$uxg$, $uxg$P14-U06$uxg$, $uxg${"en":"Make steppers clear and quick","ar":"اجعل الـ Stepper واضحًا وسريعًا"}$uxg$::jsonb, $uxg${"en":"Show the unit, grey out − or + at the limits, and let people type a big jump instead of tapping many times.","ar":"اعرض الوحدة، وعطّل − أو + عند الحدود، واسمح للناس بكتابة القفزات الكبيرة بدل الضغط مرات كثيرة."}$uxg$::jsonb),
  ($uxg$SK-P14-U06-03$uxg$, $uxg$P14-U06$uxg$, $uxg${"en":"Use sliders when close enough is fine","ar":"استخدم الـ Slider حين تكفي القيمة التقريبية"}$uxg$::jsonb, $uxg${"en":"Use a slider only for approximate values such as brightness or volume, keep its value visible while dragging, and use typing or a stepper for exact values.","ar":"استخدم الـ Slider فقط للقيم التقريبية مثل الإضاءة أو الصوت، واجعل قيمته ظاهرة أثناء السحب، واستخدم الكتابة أو الـ Stepper للقيم الدقيقة."}$uxg$::jsonb),
  ($uxg$SK-P14-U06-04$uxg$, $uxg$P14-U06$uxg$, $uxg${"en":"Match the date input to the date","ar":"اختر طريقة إدخال التاريخ المناسبة للتاريخ"}$uxg$::jsonb, $uxg${"en":"Use a calendar for dates close to today and for ranges, typing for far, known dates such as a birthdate, and a scrolling picker only for near dates or times.","ar":"استخدم التقويم للتواريخ القريبة من اليوم وللفترات، والكتابة للتواريخ البعيدة المعروفة مثل تاريخ الميلاد، والـ Scrolling picker فقط للتواريخ القريبة أو الأوقات."}$uxg$::jsonb),
  ($uxg$SK-P15-U01-01$uxg$, $uxg$P15-U01$uxg$, $uxg${"en":"Put the meaning in the first two words","ar":"ضع المعنى في أول كلمتين"}$uxg$::jsonb, $uxg${"en":"Start titles, links, buttons and list items with the words that carry the meaning, not with filler like \"Introducing\" or \"Click here to\".","ar":"ابدأ العناوين والروابط والأزرار وعناصر القوائم بالكلمات التي تحمل المعنى، لا بكلمات حشو مثل «نقدّم لكم» أو «اضغط هنا لـ»."}$uxg$::jsonb),
  ($uxg$SK-P15-U01-02$uxg$, $uxg$P15-U01$uxg$, $uxg${"en":"Lead with the main point","ar":"ابدأ بالفكرة الأهم"}$uxg$::jsonb, $uxg${"en":"Put the most important fact first in a message or page, so people who stop after one line still get it.","ar":"ضع أهم معلومة أولًا في الرسالة أو الصفحة، حتى يفهمها من يتوقّف بعد سطر واحد."}$uxg$::jsonb),
  ($uxg$SK-P15-U01-03$uxg$, $uxg$P15-U01$uxg$, $uxg${"en":"Write headings that say what's below","ar":"اكتب عناوين تقول ما تحتها"}$uxg$::jsonb, $uxg${"en":"Use specific, plain headings that still make sense when shown alone, instead of clever or vague ones.","ar":"استخدم عناوين محددة وبسيطة تُفهم حتى لو ظهرت وحدها، بدل العناوين الطريفة أو المبهمة."}$uxg$::jsonb),
  ($uxg$SK-P15-U01-04$uxg$, $uxg$P15-U01$uxg$, $uxg${"en":"Use lists the right way","ar":"استخدم القوائم بالطريقة الصحيحة"}$uxg$::jsonb, $uxg${"en":"Turn 3 or more related items into a vertical list, start every item the same way, and number it only when order or count matters.","ar":"حوّل 3 عناصر مترابطة أو أكثر إلى قائمة رأسية، وابدأ كل عنصر بنفس الطريقة، ورقّمها فقط حين يهمّ الترتيب أو العدد."}$uxg$::jsonb),
  ($uxg$SK-P15-U02-01$uxg$, $uxg$P15-U02$uxg$, $uxg${"en":"Cut filler, repeats and fancy words","ar":"احذف الحشو والتكرار والكلمات المتكلّفة"}$uxg$::jsonb, $uxg${"en":"Remove warm-up sentences, words like \"very\", repeated ideas and fancy words like \"utilize\", without losing meaning.","ar":"احذف جمل التمهيد، وكلمات مثل «جدًا»، والأفكار المكرّرة، والكلمات المتكلّفة، دون أن يضيع المعنى."}$uxg$::jsonb),
  ($uxg$SK-P15-U02-02$uxg$, $uxg$P15-U02$uxg$, $uxg${"en":"Keep the words that make it clear","ar":"أبقِ الكلمات التي توضّح المعنى"}$uxg$::jsonb, $uxg${"en":"Add or keep a few words when they tell people what will happen or what they need to decide.","ar":"أضف أو أبقِ بعض الكلمات حين تخبر الناس بما سيحدث أو بما يحتاجونه ليقرّروا."}$uxg$::jsonb),
  ($uxg$SK-P15-U02-03$uxg$, $uxg$P15-U02$uxg$, $uxg${"en":"Say who does what","ar":"قل من يفعل ماذا"}$uxg$::jsonb, $uxg${"en":"Write active sentences that name who must act, and positive steps instead of double negatives.","ar":"اكتب جملًا بصيغة المبني للمعلوم (Active voice) تذكر من عليه أن يتصرّف، وخطوات بصيغة إيجابية بدل النفي المزدوج."}$uxg$::jsonb),
  ($uxg$SK-P15-U02-04$uxg$, $uxg$P15-U02$uxg$, $uxg${"en":"Write facts as numbers","ar":"اكتب الحقائق بالأرقام"}$uxg$::jsonb, $uxg${"en":"Use digits for specific facts, explain unusual units, and keep words for numbers that aren't exact facts.","ar":"استخدم الأرقام للحقائق المحددة، واشرح الوحدات غير المألوفة، واترك الكلمات للأعداد التي ليست حقائق دقيقة."}$uxg$::jsonb),
  ($uxg$SK-P15-U03-01$uxg$, $uxg$P15-U03$uxg$, $uxg${"en":"Hear the tone","ar":"اسمع النبرة"}$uxg$::jsonb, $uxg${"en":"Place a text on the 4 tone scales (formal or casual, serious or funny, respectful or irreverent, matter-of-fact or enthusiastic) and change one without the others.","ar":"حدّد مكان النص على مقاييس النبرة الأربعة (رسمي أو ودّي، جاد أو مضحك، محترم أو ساخر، محايد أو متحمّس)، وغيّر واحدًا منها دون الباقي."}$uxg$::jsonb),
  ($uxg$SK-P15-U03-02$uxg$, $uxg$P15-U03$uxg$, $uxg${"en":"Fit the tone to the moment","ar":"اجعل النبرة تناسب اللحظة"}$uxg$::jsonb, $uxg${"en":"Choose a tone that fits how people feel right now: calm and clear when they are worried or frustrated, warmer when the news is good.","ar":"اختر نبرة تناسب شعور الناس الآن: هادئة وواضحة حين يكونون قلقين أو منزعجين، وأكثر دفئًا حين يكون الخبر سعيدًا."}$uxg$::jsonb),
  ($uxg$SK-P15-U03-03$uxg$, $uxg$P15-U03$uxg$, $uxg${"en":"Be serious without being cold","ar":"كن جادًا دون أن تكون باردًا"}$uxg$::jsonb, $uxg${"en":"Write about money, health and safety in plain, friendly words, without jokes that cost trust.","ar":"اكتب عن المال والصحة والأمان بكلمات بسيطة وودّية، دون نكات تُفقدك الثقة."}$uxg$::jsonb),
  ($uxg$SK-P15-U03-04$uxg$, $uxg$P15-U03$uxg$, $uxg${"en":"One voice, many tones","ar":"صوت واحد ونبرات كثيرة"}$uxg$::jsonb, $uxg${"en":"Keep the brand's personality the same everywhere, describe the tone in a few words, and check it with real users instead of guessing.","ar":"حافظ على شخصية العلامة نفسها في كل مكان، وصِف النبرة بكلمات قليلة، وتحقّق منها مع مستخدمين حقيقيين بدل التخمين."}$uxg$::jsonb),
  ($uxg$SK-P15-U04-01$uxg$, $uxg$P15-U04$uxg$, $uxg${"en":"Start buttons with a clear verb","ar":"ابدأ الأزرار بفعل واضح"}$uxg$::jsonb, $uxg${"en":"Label buttons with a specific verb, and a noun when needed, in 2 to 4 words, and use the same label for the same action everywhere.","ar":"اكتب على الأزرار فعلًا محددًا، واسمًا عند الحاجة، في 2 إلى 4 كلمات، واستخدم نفس النص لنفس الفعل في كل مكان."}$uxg$::jsonb),
  ($uxg$SK-P15-U04-02$uxg$, $uxg$P15-U04$uxg$, $uxg${"en":"Name the next state","ar":"سمِّ الحالة التالية"}$uxg$::jsonb, $uxg${"en":"Label a switching button with what it will do next, like Pause while playing, and name style changes with the style itself, like Bold.","ar":"اكتب على زر التبديل (Toggle) ما سيفعله بعد الضغط، مثل «إيقاف مؤقت» أثناء التشغيل، وسمِّ تغييرات الشكل باسم الشكل نفسه، مثل Bold."}$uxg$::jsonb),
  ($uxg$SK-P15-U04-03$uxg$, $uxg$P15-U04$uxg$, $uxg${"en":"Write confirmations people read","ar":"اكتب رسائل تأكيد يقرؤها الناس"}$uxg$::jsonb, $uxg${"en":"Name the item and the result in a confirmation, and give buttons that say what each choice does, like Delete file and Keep file.","ar":"اذكر العنصر والنتيجة في رسالة التأكيد، وضع أزرارًا تقول ما يفعله كل خيار، مثل «احذف الملف» و«أبقِ الملف»."}$uxg$::jsonb),
  ($uxg$SK-P15-U04-04$uxg$, $uxg$P15-U04$uxg$, $uxg${"en":"Write links that keep their promise","ar":"اكتب روابط تفي بوعدها"}$uxg$::jsonb, $uxg${"en":"Write link labels that make sense on their own, say where they lead, and lead exactly there.","ar":"اكتب روابط مفهومة وحدها، تقول إلى أين تأخذك، وتأخذك إلى هناك بالضبط."}$uxg$::jsonb),
  ($uxg$SK-P15-U05-01$uxg$, $uxg$P15-U05$uxg$, $uxg${"en":"Explain the empty screen","ar":"اشرح الشاشة الفارغة"}$uxg$::jsonb, $uxg${"en":"Say what will appear in an empty area and how to fill it, and never say \"nothing here\" while content is still loading.","ar":"قل ما الذي سيظهر في المساحة الفارغة وكيف تُملأ، ولا تقل أبدًا «لا يوجد شيء» بينما المحتوى ما زال يُحمَّل."}$uxg$::jsonb),
  ($uxg$SK-P15-U05-02$uxg$, $uxg$P15-U05$uxg$, $uxg${"en":"Give a direct way to start","ar":"أعطِ طريقًا مباشرًا للبدء"}$uxg$::jsonb, $uxg${"en":"Put a button or link in the empty screen that starts the task, instead of only telling people where to go.","ar":"ضع في الشاشة الفارغة زرًّا أو رابطًا يبدأ المهمة، بدل أن تخبر الناس فقط إلى أين يذهبون."}$uxg$::jsonb),
  ($uxg$SK-P15-U05-03$uxg$, $uxg$P15-U05$uxg$, $uxg${"en":"Ask for notifications at the right time","ar":"اطلب الإذن بالإشعارات في الوقت المناسب"}$uxg$::jsonb, $uxg${"en":"Ask after people have seen the app's value, and say what the notifications will be about.","ar":"اطلب بعد أن يرى الناس فائدة التطبيق، وقل موضوع الإشعارات."}$uxg$::jsonb),
  ($uxg$SK-P15-U05-04$uxg$, $uxg$P15-U05$uxg$, $uxg${"en":"Send notifications worth reading","ar":"أرسل إشعارات تستحق القراءة"}$uxg$::jsonb, $uxg${"en":"Send only what matters to this person, and combine many updates into one message.","ar":"أرسل فقط ما يهمّ هذا الشخص، واجمع التحديثات الكثيرة في رسالة واحدة."}$uxg$::jsonb)
